﻿import { RpcClient } from '../rpc'
import { StorageApi } from './StorageApi.ts'

export interface MethodIds {
  clear: string
  getItem: string
  getKey: string
  length: string
  removeItem: string
  setItem: string
  getAllItems?: string
  getAllData?: string
  removeMultipleItems?: string
  setMultipleItems?: string
}

export class RpcStorageApi implements StorageApi {
  private readonly rpcClient: RpcClient
  private readonly methodIds: MethodIds
  /**
   * Extra body fields merged into every RPC call. Used by shared-scope
   * bindings to carry (targetAppId, namespace) alongside the op-specific
   * arguments. `undefined` for app/owner bindings.
   */
  private readonly extraBodyFields?: Record<string, string>

  constructor(
    rpcClient: RpcClient,
    methodIds: MethodIds,
    extraBodyFields?: Record<string, string>,
  ) {
    this.rpcClient = rpcClient
    this.methodIds = methodIds
    this.extraBodyFields = extraBodyFields
  }

  private body(extra?: Record<string, unknown>): Record<string, unknown> | undefined {
    if (!this.extraBodyFields && !extra) return undefined
    return { ...(this.extraBodyFields ?? {}), ...(extra ?? {}) }
  }

  clear(): Promise<void> {
    return this.rpcClient.call(this.methodIds.clear, this.body())
  }

  getItem(key: string): Promise<string | null> {
    return this.rpcClient.call(this.methodIds.getItem, this.body({ key }))
  }

  setItem(key: string, value: string): Promise<void> {
    return this.rpcClient.call(this.methodIds.setItem, this.body({ key, value }))
  }

  key(index: number): Promise<string | null> {
    return this.rpcClient.call(this.methodIds.getKey, this.body({ index }))
  }

  length(): Promise<number> {
    return this.rpcClient.call(this.methodIds.length, this.body())
  }

  removeItem(key: string): Promise<void> {
    return this.rpcClient.call(this.methodIds.removeItem, this.body({ key }))
  }

  removeMultipleItems(keys: string[]): Promise<void> {
    if (!this.methodIds.removeMultipleItems) {
      throw new Error('Method not implemented')
    }
    return this.rpcClient.call(this.methodIds.removeMultipleItems, this.body({ keys }))
  }

  getAllItems(): Promise<string[]> {
    if (!this.methodIds.getAllItems) {
      throw new Error('Method not implemented')
    }
    return this.rpcClient.call(this.methodIds.getAllItems, this.body())
  }

  getAllData(): Promise<Record<string, string>> {
    if (!this.methodIds.getAllData) {
      throw new Error('Method not implemented')
    }
    return this.rpcClient.call(this.methodIds.getAllData, this.body())
  }

  setMultipleItems(items: { key: string; value: string }[]): Promise<void> {
    if (!this.methodIds.setMultipleItems) {
      throw new Error('Method not implemented')
    }
    return this.rpcClient.call(this.methodIds.setMultipleItems, this.body({ items }))
  }
}
