import { base64DecodeInto } from './base64Utils'

/**
 * A source of base64-encoded byte slices of a fixed-size asset.
 * `readChunk(position, length)` must return the base64 encoding of the bytes
 * it actually read starting at `position` — which may be FEWER than `length`
 * (short read), but never more.
 */
export interface ChunkedAssetSource {
  totalBytes: number
  chunkBytes: number
  readChunk: (position: number, length: number) => Promise<string>
}

/**
 * Assemble an asset by pulling it chunk-by-chunk from `source`.
 *
 * Invariants (all structural, see venus issue #2749):
 * - The cursor advances by the ACTUAL decoded byte count of each chunk, so
 *   short reads self-heal: the next request re-starts at the real cursor.
 * - `length` is always clamped to `totalBytes - position` and a request is
 *   never issued at `position >= totalBytes` (Android's native read at EOF
 *   returns -1 and its base64 encoder throws on a negative count).
 * - A zero-byte chunk cannot advance the cursor and would loop forever, so
 *   it is an error.
 * - Each chunk gets exactly ONE retry; a second failure aborts the whole
 *   transfer. Callers decide what a failed transfer falls back to.
 */
export async function readAssetInChunks(source: ChunkedAssetSource): Promise<ArrayBuffer> {
  const { totalBytes, chunkBytes } = source

  if (!Number.isSafeInteger(totalBytes) || totalBytes < 0) {
    throw new Error(`Invalid chunked asset size: ${totalBytes}`)
  }
  if (!Number.isSafeInteger(chunkBytes) || chunkBytes < 1) {
    throw new Error(`Invalid chunk size: ${chunkBytes}`)
  }

  const assembled = new Uint8Array(totalBytes)
  let received = 0

  while (received < totalBytes) {
    const length = Math.min(chunkBytes, totalBytes - received)
    received += await readChunkWithRetry(source, received, length, assembled)
  }

  return assembled.buffer
}

async function readChunkWithRetry(
  source: ChunkedAssetSource,
  position: number,
  length: number,
  target: Uint8Array,
): Promise<number> {
  try {
    return await readChunkInto(source, position, length, target)
  } catch {
    return readChunkInto(source, position, length, target)
  }
}

async function readChunkInto(
  source: ChunkedAssetSource,
  position: number,
  length: number,
  target: Uint8Array,
): Promise<number> {
  const base64Data = await source.readChunk(position, length)
  const decoded = base64DecodeInto(base64Data, target, position)
  if (decoded === 0) {
    throw new Error(`Empty chunk at position ${position} of ${target.length}`)
  }
  if (decoded > length) {
    throw new Error(
      `Chunk at position ${position} returned ${decoded} bytes, more than the ${length} requested`,
    )
  }
  return decoded
}
