import { RpcRequest } from './RpcRequest.ts'
import { RpcResponse } from './RpcResponse.ts'
import { RpcTransport } from './RpcTransport.ts'
import { RpcNotification } from './RpcNotification'
import { generateId } from '../utils/idGenerator'
import { RateLimitedError, RundotApiError } from '../errors'

interface PendingCall {
  id: string
  resolve: (value: unknown) => void
  reject: (error: unknown) => void
}

export interface Subscription {
  unsubscribe: () => void
}

type NotificationCallback = (payload: unknown) => void

export class RpcClient {
  private readonly pendingCalls = new Map<string, PendingCall>()
  // Multiple subscribers per notification id are required (e.g. concurrent
  // streaming chat completions each subscribe to STREAM_CHUNK and dispatch
  // by streamId). A single-slot Map silently overwrote subscribers; now
  // each id maps to a Set so registration / removal is O(1) and dispatch
  // fans out to every subscriber.
  private readonly notificationCallbacks = new Map<string, Set<NotificationCallback>>()

  private onResponseSub: Subscription | null = null
  private onNotificationSub: Subscription | null = null
  private transport: RpcTransport | null = null

  start(transport: RpcTransport): void {
    this.transport = transport
    this.onResponseSub = transport.onResponse(async (response) => {
      return this.handleRpcResponse(response)
    })
    this.onNotificationSub = transport.onNotification(async (notification) => {
      return this.handleRpcNotification(notification)
    })
  }

  stop(): void {
    if (this.onResponseSub) {
      this.onResponseSub.unsubscribe()
      this.onResponseSub = null
    }

    if (this.onNotificationSub) {
      this.onNotificationSub.unsubscribe()
      this.onNotificationSub = null
    }

    this.transport = null
  }

  onNotification<TPayload>(
    id: string,
    callback: (payload: TPayload) => void,
  ): Subscription {
    const typed = callback as NotificationCallback
    let subscribers = this.notificationCallbacks.get(id)
    if (!subscribers) {
      subscribers = new Set<NotificationCallback>()
      this.notificationCallbacks.set(id, subscribers)
    }
    subscribers.add(typed)
    return {
      unsubscribe: () => {
        const set = this.notificationCallbacks.get(id)
        if (!set) return
        set.delete(typed)
        if (set.size === 0) {
          this.notificationCallbacks.delete(id)
        }
      },
    }
  }

  callT<TArgs, TResult>(
    method: string,
    args?: TArgs,
    timeout: number = 60000,
  ): Promise<TResult> {
    return this.call(method, args, timeout)
  }

  async call<TResponse>(
    method: string,
    args?: unknown,
    timeout: number = 60000,
  ): Promise<TResponse> {
    // NOTE(Zee): Make this into options?
    return new Promise((resolve, reject) => {
      const id = generateId()
      this.addPendingCall(
        id,
        (value: unknown) => resolve(value as TResponse),
        (error: unknown) => reject(error),
      )

      const request: RpcRequest = {
        type: 'rpc-request',
        id,
        method,
        args: args,
      }

      if (this.transport) {
        this.transport.sendRequest(request)
      }

      // NOTE(Zee): This is dangerous. We REALLY need to rely on the host to send back a response, otherwise we may permanently hang here...
      if (timeout > 0) {
        const startTime = Date.now()
        setTimeout(() => {
          if (this.hasPendingCall(id)) {
            this.removePendingCall(id)
            const elapsed = Date.now() - startTime
            console.error(
              `[RpcClient] TIMEOUT: ${method} after ${elapsed}ms (limit: ${timeout}ms)`,
              {
                method,
                id,
                args: this.safeStringifyArgs(args).substring(0, 500),
                timeout,
                elapsed,
                timestamp: new Date().toISOString(),
              },
            )
            reject(new RundotApiError('TIMEOUT', `RPC call ${method} timed out after ${elapsed}ms`, 0))
          }
        }, timeout)
      }
    })
  }

  /**
   * Send a fire-and-forget RPC request.
   *
   * Unlike `call()`, `notify()`:
   *   - does NOT register a pending call,
   *   - does NOT arm a timeout,
   *   - does NOT await or surface the host's response.
   *
   * Use this for telemetry / cleanup RPCs where the caller does not care about
   * the result and does not want spurious timeout errors when the iframe is
   * throttled (e.g. backgrounded tab) or the host's response is otherwise
   * late. Host-side errors are NOT surfaced to the caller.
   *
   * The wire format is identical to `call()` (an `rpc-request` with a
   * generated id), so any late response from the host is harmlessly dropped
   * by `handleRpcResponse` — there is no entry in `pendingCalls` to match.
   */
  notify(method: string, args?: unknown): void {
    const id = generateId()

    const request: RpcRequest = {
      type: 'rpc-request',
      id,
      method,
      args: args,
    }

    if (this.transport) {
      this.transport.sendRequest(request)
    }
  }

  private hasPendingCall(id: string): boolean {
    return this.pendingCalls.has(id)
  }

  private safeStringifyArgs(args: unknown): string {
    if (args === undefined) {
      return 'undefined'
    }
    if (args === null) {
      return 'null'
    }
    try {
      const serialized = JSON.stringify(args)
      if (serialized === undefined) {
        return 'undefined'
      }
      return serialized
    } catch (error) {
      return `[unserializable args: ${String(error)}]`
    }
  }

  private addPendingCall(
    id: string,
    resolve: (v: unknown) => void,
    reject: (e: unknown) => void,
  ): void {
    this.pendingCalls.set(id, {
      id: id,
      resolve: resolve,
      reject: reject,
    })
  }

  private removePendingCall(id: string): void {
    this.pendingCalls.delete(id)
  }

  private getPendingCall(id: string): PendingCall | undefined {
    return this.pendingCalls.get(id)
  }

  private handleRpcResponse(response: RpcResponse): boolean {
    const pending = this.getPendingCall(response.id)
    if (!pending) {
      return false
    }
    this.removePendingCall(response.id)

    if (response.error) {
      const { message, code, detail, errorDetail, retryAfterMs } = response.error
      if (code === 'RATE_LIMITED') {
        pending.reject(new RateLimitedError(retryAfterMs ?? 1_000, message))
        return true
      }
      pending.reject(new RundotApiError(code ?? 'UNKNOWN', message, 0, detail, errorDetail))
      return true
    }

    pending.resolve(response.result)
    return true
  }

  private handleRpcNotification(notification: RpcNotification): void {
    const subscribers = this.notificationCallbacks.get(notification.id)
    if (!subscribers) return
    // Snapshot before iteration: a subscriber unsubscribing inside its own
    // callback (or any other subscriber's callback) mutates the live Set,
    // and iterating the live Set during mutation can skip or double-fire.
    for (const callback of [...subscribers]) {
      callback(notification.payload)
    }
  }
}
