﻿import { LoggingApi } from './LoggingApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { Host } from '../Host'

export class RpcLoggingApi implements LoggingApi {
  private readonly host: Host
  private readonly rpcClient: RpcClient

  constructor(host: Host, rpcClient: RpcClient) {
    this.host = host
    this.rpcClient = rpcClient
  }

  logDebug(message: string, ...args: any[]): void {
    if (!this.host.isInitialized) {
      console.log(message, args)
      return
    }
    // Fire-and-forget: `notify()` does not arm an RPC timeout. `call()` would
    // reject after 60s as an unhandled page error when the iframe is throttled
    // (e.g. an offscreen pooled iframe), stalling launch and tripping the
    // host's launch watchdog into re-showing a duplicate iframe.
    this.rpcClient.notify(
      RundotGameMessageId.DEBUG,
      { level: 'log', message: this.buildMessage(message, ...args) },
    )
  }

  logError(message: string, ...args: any[]): void {
    if (!this.host.isInitialized) {
      console.error(message, ...args)
      return
    }
    this.rpcClient.notify(
      RundotGameMessageId.DEBUG,
      { level: 'error', message: this.buildMessage(message, ...args) },
    )
  }

  private buildMessage(message: string, ...args: any[]): string {
    // Handle multiple parameters like console.error
    if (args && args.length > 0) {
      const stringArgs: string[] = []
      for (const arg of args) {
        const argAsString = this.toStringArg(arg)
        if (argAsString) {
          stringArgs.push(argAsString)
        }
      }
      message += stringArgs.join(' ')
    }
    return message
  }

  private toStringArg(arg: any) {
    if (arg instanceof Error) {
      return `${arg.name}: ${arg.message}`
    }
    if (arg) {
      if (typeof arg === 'object') {
        try {
          return JSON.stringify(arg)
        } catch (e) {
          return String(arg)
        }
      }
      return String(arg)
    }
    return undefined
  }
}
