﻿import { RundotGameAPI } from '../rundot-game-api/types.ts'
import { Host } from '../Host'

export * from './ProfileApi'
export * from './HostProfileApi'
export * from './MockProfileApi'
export * from './PlaygroundProfileApi'

import { PlaygroundProfileApi } from './PlaygroundProfileApi'
import { warnRenamed } from '../deprecationWarning'
/** @deprecated Use `PlaygroundProfileApi`. */
export class SandboxProfileApi extends PlaygroundProfileApi { // @deprecated-alias
  constructor(...args: ConstructorParameters<typeof PlaygroundProfileApi>) {
    warnRenamed('SandboxProfileApi', 'PlaygroundProfileApi') // @deprecated-alias
    super(...args)
  }
}

export function initializeProfile(rundotGameApi: RundotGameAPI, host: Host) {
  // New API
  rundotGameApi.getProfile = () => {
    return host.profile.getCurrentProfile()
  }
  
  // Deprecated API - kept for backwards compatibility
  rundotGameApi.getCurrentProfile = () => {
    console.warn(
      '[RUN] DEPRECATED: RundotGameAPI.getCurrentProfile() is deprecated. ' +
      'Use RundotGameAPI.getProfile() instead. ' +
      'See migration guide: https://docs.rundot-game.com/migration/profile-api'
    )
    return host.profile.getCurrentProfile()
  }
}
