﻿import { HapticFeedbackStyle, HapticsApi } from './HapticsApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'

export class RpcHapticsApi implements HapticsApi {
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async triggerHapticAsync(style: HapticFeedbackStyle): Promise<void> {
    await this.rpcClient.call(RundotGameMessageId.TRIGGER_HAPTIC, {
      style: style,
    })
  }
}
