import type { RpcClient, Subscription } from '../rpc'
import type { RundotGameAPI } from '../rundot-game-api/types'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { sanitizeProfile } from '../access-gate/sanitizeProfile'
import type { IdentityChangedEvent } from './LifecycleApi'

/**
 * Subscribes an internal handler that overwrites `rundotGameApi._profileData`
 * with the canonical profile the instant an IDENTITY_CHANGED notification
 * arrives. RemoteHost MUST call this during initialization, before any game
 * code subscribes via `lifecycle.onIdentityChanged`, so that the replica is
 * already up to date when game callbacks run (RpcClient fans out to
 * subscribers in registration order). A game reading `api.profile` inside its
 * own handler then sees the new identity, not the stale one.
 */
export function wireIdentityReplica(
  rpcClient: RpcClient,
  rundotGameApi: RundotGameAPI,
): Subscription {
  return rpcClient.onNotification<IdentityChangedEvent>(
    RundotGameMessageId.IDENTITY_CHANGED,
    (event) => {
      if (event?.profile) {
        rundotGameApi._profileData = sanitizeProfile(event.profile)
      }
    },
  )
}
