import { StatsApi, GrantInfo } from './StatsApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'

interface PendingResolver {
  resolve: (value: { grants: GrantInfo[] }) => void
  reject: (reason: unknown) => void
}

/** Per-stat batch entry. The value is last-write-wins; the resolvers list
 *  collects every caller waiting on this specific statId in the current batch
 *  so they can all be resolved or rejected based on the stat's own outcome. */
interface PendingStat {
  value: number
  resolvers: PendingResolver[]
}

/** Shape of one entry in the bridge's batch response. */
interface BatchStatResult {
  statId: string
  ok: boolean
  grants?: GrantInfo[]
  error?: string
}

/**
 * Production StatsApi backed by the SDK's RPC bridge.
 *
 * Coalescing model: every `submit()` call within a single synchronous tick
 * joins the same pending batch. The batch is flushed on the next microtask
 * via `Promise.resolve().then(...)` — one RPC per tick. This collapses the
 * common case (game loop calling submit several times in a frame) into a
 * single round-trip without using timers, which the repo style rules
 * disallow for coordination.
 *
 * Per-stat last-write-wins on value; per-stat demux on response — see the
 * StatsApi interface doc for the caller contract.
 *
 * Read methods (`getValue`, `getAllValues`) are direct RPC calls.
 *
 * No lifecycle hooks are wired: a microtask drains at every event-loop
 * checkpoint, so any pending submit is flushed before the browser reaches
 * an unload checkpoint. There is nothing left "pending past tick" to flush.
 */
export class RpcStatsApi implements StatsApi {
  private readonly rpcClient: RpcClient
  private pending = new Map<string, PendingStat>()
  private scheduledFlush = false

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async submit(statId: string, value: number): Promise<{ grants: GrantInfo[] }> {
    return new Promise<{ grants: GrantInfo[] }>((resolve, reject) => {
      const resolver: PendingResolver = { resolve, reject }
      const existing = this.pending.get(statId)
      if (existing) {
        existing.value = value
        existing.resolvers.push(resolver)
      } else {
        this.pending.set(statId, { value, resolvers: [resolver] })
      }
      this.scheduleFlush()
    })
  }

  async getValue(statId: string): Promise<number | null> {
    const response = await this.rpcClient.call<{ value: number | null }>(
      RundotGameMessageId.H5_STATS_GET_VALUE,
      { statId },
    )
    return response.value
  }

  async getAllValues(): Promise<Record<string, number>> {
    const response = await this.rpcClient.call<{ stats: Record<string, number> }>(
      RundotGameMessageId.H5_STATS_GET_ALL,
      {},
    )
    return response.stats
  }

  // ── internals ──

  private scheduleFlush(): void {
    if (this.scheduledFlush) return
    this.scheduledFlush = true
    // Microtask, not setTimeout: queues for the next event-loop checkpoint
    // and runs before any I/O or unload step in the same task.
    void Promise.resolve().then(() => this.flushNow())
  }

  private async flushNow(): Promise<void> {
    this.scheduledFlush = false
    if (this.pending.size === 0) return

    // Snapshot pending state before the await so any submits that arrive
    // during the in-flight RPC don't get folded into this batch — they'll
    // schedule their own microtask flush.
    const batchValues: Record<string, number> = {}
    const resolversByStatId = new Map<string, PendingResolver[]>()
    for (const [statId, entry] of this.pending) {
      batchValues[statId] = entry.value
      resolversByStatId.set(statId, entry.resolvers)
    }
    this.pending = new Map()

    try {
      const results = await this.sendBatch(batchValues)
      const resultsByStatId = new Map(results.map((r) => [r.statId, r]))
      for (const [statId, resolvers] of resolversByStatId) {
        const r = resultsByStatId.get(statId)
        if (!r || !r.ok) {
          const err = new Error(r?.error ?? 'stat submit failed')
          for (const resolver of resolvers) resolver.reject(err)
        } else {
          for (const resolver of resolvers) resolver.resolve({ grants: r.grants ?? [] })
        }
      }
    } catch (err) {
      // Whole bridge call failed — propagate to every coalesced caller.
      for (const [, resolvers] of resolversByStatId) {
        for (const resolver of resolvers) resolver.reject(err)
      }
    }
  }

  private async sendBatch(stats: Record<string, number>): Promise<BatchStatResult[]> {
    const response = await this.rpcClient.call<{ results: BatchStatResult[] }>(
      RundotGameMessageId.H5_STATS_SUBMIT_BATCH,
      { stats },
    )
    return response.results ?? []
  }
}
