import type { TextGenApi } from '../textGen/TextGenApi'
import type { ImageGenApi } from '../imageGen/ImageGenApi'
import type { AudioGenApi } from '../audioGen/AudioGenApi'
import type { SpriteGenApi } from '../spriteGen/SpriteGenApi'
import type { ThreeDGenApi } from '../threeDGen/ThreeDGenApi'
import type { UgcApi } from '../ugc/UgcApi'
import type { RoomsApi } from '../rooms/RoomsApi'
import type { SimulationApi } from '../simulation/SimulationApi'
import type { MultiplayerApi } from '../mp/client/MultiplayerApi'
import type { AccessGateApi } from './AccessGateApi'
import { createAccessGatedApi } from './createAccessGatedApi'
import type { AccessGateConfig } from './createAccessGatedApi'
import { gateStreaming } from './gateStreaming'
import type {
  AiChatCompletionRequest,
  AiChatCompletionStreamOptions,
  PromptCompletionRequest,
} from '../ai/AiApi'

export interface GatableHost {
  accessGate: AccessGateApi
  textGen: TextGenApi
  imageGen: ImageGenApi
  audioGen: AudioGenApi
  spriteGen: SpriteGenApi
  threeDGen: ThreeDGenApi
  ugc: UgcApi
  rooms: RoomsApi
  simulation: SimulationApi
  multiplayer: MultiplayerApi
}

/**
 * Wraps gated API methods on a host with access-gate checks.
 * Call this once during host construction, after all API instances
 * and the accessGate have been assigned.
 */
export function applyAccessGates(host: GatableHost): void {
  const gateConfig: AccessGateConfig = {
    isAnonymous: () => host.accessGate.isAnonymous(),
    promptLogin: () => host.accessGate.promptLogin(),
    isAutoPromptEnabled: () => host.accessGate.autoPromptLogin,
  }

  // `requestChatCompletionStreamAsync` can't go through `createAccessGatedApi`
  // (it wraps return values as Promises, breaking the `AsyncIterable<chunk>`
  // contract). Instead `gateStreaming` returns an AsyncIterable that runs the
  // access check on first iteration — prompting BEFORE the stream START, so an
  // anonymous user signs in mid-session and the stream opens authenticated.
  const baseTextGen = host.textGen
  const gatedStream = gateStreaming(
    (request: AiChatCompletionRequest, options?: AiChatCompletionStreamOptions) =>
      baseTextGen.requestChatCompletionStreamAsync(request, options),
    gateConfig,
  )
  const gatedPromptStream = gateStreaming(
    (request: PromptCompletionRequest, options?: AiChatCompletionStreamOptions) =>
      baseTextGen.requestPromptCompletionStreamAsync(request, options),
    gateConfig,
  )
  const gatedTextGen = createAccessGatedApi(
    baseTextGen,
    ['requestChatCompletionAsync', 'requestPromptCompletionAsync', 'getAvailableCompletionModels'],
    'authenticated_18plus',
    gateConfig,
  )
  host.textGen = new Proxy(gatedTextGen, {
    get(target, prop, receiver) {
      if (prop === 'requestChatCompletionStreamAsync') {
        return gatedStream
      }
      if (prop === 'requestPromptCompletionStreamAsync') {
        return gatedPromptStream
      }
      return Reflect.get(target, prop, receiver)
    },
  })

  host.imageGen = createAccessGatedApi(
    host.imageGen,
    ['generate', 'estimateDepth', 'removeBackground'],
    'authenticated_18plus',
    gateConfig,
  )

  host.audioGen = createAccessGatedApi(
    host.audioGen,
    ['generate', 'designVoices', 'saveDesignedVoice'],
    'authenticated_18plus',
    gateConfig,
  )

  host.spriteGen = createAccessGatedApi(
    host.spriteGen,
    ['generate', 'animate'],
    'authenticated_18plus',
    gateConfig,
  )

  host.threeDGen = createAccessGatedApi(
    host.threeDGen,
    ['generate', 'remesh', 'rig', 'animate'],
    'authenticated_18plus',
    gateConfig,
  )

  host.ugc = createAccessGatedApi(
    host.ugc,
    ['create', 'update', 'delete', 'like', 'unlike', 'report'],
    'authenticated_18plus',
    gateConfig,
  )

  host.rooms = createAccessGatedApi(
    host.rooms,
    [
      'createRoomAsync',
      'joinOrCreateRoomAsync',
      'joinRoomByCodeAsync',
      'getUserRoomsAsync',
      'subscribeAsync',
      'updateRoomDataAsync',
      'getRoomDataAsync',
      'sendRoomMessageAsync',
      'leaveRoomAsync',
      'kickPlayerAsync',
      'startRoomGameAsync',
      'proposeMoveAsync',
      'validateMoveAsync',
    ],
    'authenticated_18plus',
    gateConfig,
  )

  // Realtime multiplayer entry points. `send` and `leave` live on the
  // returned `ServerRoom` instance, which is only obtainable through one
  // of these gated entry points, so they inherit the gate transitively.
  host.multiplayer = createAccessGatedApi(
    host.multiplayer,
    ['createRoom', 'joinOrCreateRoom', 'joinRoomByCode', 'getUserRooms'],
    'authenticated_18plus',
    gateConfig,
  )
}
