import { RpcClient, Subscription, isUnsupportedMessageError } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import {
  ActivityActionEvent,
  ActivityApi,
  ActivityIntent,
  EndActivityInput,
  StartActivityResult,
  UpdateActivityInput,
  isActivityActionEvent,
} from './ActivityApi'

export class RpcActivityApi implements ActivityApi {
  constructor(private readonly rpcClient: RpcClient) {}

  async startActivityAsync(intent: ActivityIntent): Promise<StartActivityResult> {
    try {
      return await this.rpcClient.call<StartActivityResult>(
        RundotGameMessageId.ACTIVITY_START,
        intent,
      )
    } catch (error) {
      // A host installed before the activity protocol has no handler for this
      // message and rejects with "Unsupported message type". The documented
      // contract is a normal `skipped` result on an ineligible surface (a phone
      // today, an un-updated app), so degrade to that rather than surfacing a
      // rejection the game never opted into. The game still gets an activityId
      // per the contract; updateActivity/endActivityAsync with it are no-ops.
      if (isUnsupportedMessageError(error)) {
        return {
          activityId: `unsupported:${intent.key}`,
          status: 'skipped',
          reason: 'unsupported_surface',
        }
      }
      throw error
    }
  }

  updateActivity(input: UpdateActivityInput): void {
    this.rpcClient.notify(RundotGameMessageId.ACTIVITY_UPDATE, input)
  }

  async endActivityAsync(input: EndActivityInput): Promise<void> {
    try {
      await this.rpcClient.call<void>(RundotGameMessageId.ACTIVITY_END, input)
    } catch (error) {
      // Same legacy-host tolerance as startActivityAsync: an activity skipped
      // for want of a presenter has nothing to end, and the docs promise ending
      // it is harmless — resolve rather than reject.
      if (isUnsupportedMessageError(error)) return
      throw error
    }
  }

  onActivityAction(callback: (event: ActivityActionEvent) => void): Subscription {
    return this.rpcClient.onNotification(
      RundotGameMessageId.ACTIVITY_ACTION,
      (payload: unknown) => {
        if (!isActivityActionEvent(payload)) return
        callback(payload)
      },
    )
  }
}
