import { SharedAssetsApi } from './SharedAssetsApi'
import { RpcClient } from '../rpc'
import { isUnsupportedMessageError } from '../rpc/isUnsupportedMessageError'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { RundotGameAPI } from '../rundot-game-api'
import { base64ToArrayBuffer } from './base64Utils'
import { readAssetInChunks } from './chunkedAssetReader'

/**
 * SDK-side ceiling for chunk requests. The effective chunk size is
 * min(this, host's maxChunkBytes): shipped games pin their SDK version while
 * the host app keeps updating, so the tunable ceiling lives host-side.
 */
const DEFAULT_CHUNK_BYTES = 2 * 1024 * 1024

export class RpcSharedAssetsApi implements SharedAssetsApi {
  private readonly rundotGameApi: RundotGameAPI
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient, rundotGameApi: RundotGameAPI) {
    this.rpcClient = rpcClient
    this.rundotGameApi = rundotGameApi
  }

  async loadAssetsBundle(game: string, bundleKey: string, fileType: string = 'stow'): Promise<ArrayBuffer> {
    try {
      return await this.loadViaHostRpc(bundleKey)
    } catch (err) {
      try {
        // Use fetchFromCdn for cross-game shared assets (bypasses manifest lookup)
        const blob = await this.rundotGameApi.cdn.fetchFromCdn(`${game}/${bundleKey}.${fileType}`)
        return await blob.arrayBuffer()
      } catch (e) {
        throw new Error(`Failed to load ${bundleKey}`)
      }
    }
  }

  /**
   * Pull the asset from the host in chunks. Only a host that predates the
   * chunk protocol (BEGIN rejected with "Unsupported message type") falls
   * back to the legacy single-shot RPC. A failure DURING the chunked
   * transfer must NOT fall back to single-shot: pushing the whole asset
   * through the bridge in one message is the exact Android wedge this
   * protocol exists to avoid (venus issue #2749). Those errors propagate to
   * the caller's CDN fallback instead.
   */
  private async loadViaHostRpc(bundleKey: string): Promise<ArrayBuffer> {
    let begin: LoadEmbeddedAssetBeginResponse
    try {
      begin = await this.rpcClient.callT<
        LoadEmbeddedAssetBeginRequest,
        LoadEmbeddedAssetBeginResponse
      >(RundotGameMessageId.H5_LOAD_EMBEDDED_ASSET_BEGIN, {
        assetKey: bundleKey,
      })
    } catch (error) {
      if (isUnsupportedMessageError(error)) {
        return this.loadSingleShot(bundleKey)
      }
      throw error
    }

    if (!Number.isSafeInteger(begin.maxChunkBytes) || begin.maxChunkBytes < 1) {
      throw new Error(`Host returned invalid maxChunkBytes: ${begin.maxChunkBytes}`)
    }

    return readAssetInChunks({
      totalBytes: begin.totalBytes,
      chunkBytes: Math.min(DEFAULT_CHUNK_BYTES, begin.maxChunkBytes),
      readChunk: async (position, length) => {
        const chunk = await this.rpcClient.callT<
          LoadEmbeddedAssetChunkRequest,
          LoadEmbeddedAssetChunkResponse
        >(RundotGameMessageId.H5_LOAD_EMBEDDED_ASSET_CHUNK, {
          assetKey: bundleKey,
          position,
          length,
        })
        return chunk.base64Data
      },
    })
  }

  private async loadSingleShot(bundleKey: string): Promise<ArrayBuffer> {
    const response = await this.rpcClient.callT<
      LoadEmbeddedAssetsRequest,
      LoadEmbeddedAssetsResponse
    >(RundotGameMessageId.H5_LOAD_EMBEDDED_ASSET, {
      assetKey: bundleKey,
    })
    return base64ToArrayBuffer(response.base64Data)
  }
}

export interface LoadEmbeddedAssetsRequest {
  assetKey: string
}

export interface LoadEmbeddedAssetsResponse {
  base64Data: string
}

export interface LoadEmbeddedAssetBeginRequest {
  assetKey: string
}

export interface LoadEmbeddedAssetBeginResponse {
  totalBytes: number
  maxChunkBytes: number
}

export interface LoadEmbeddedAssetChunkRequest {
  assetKey: string
  position: number
  length: number
}

export interface LoadEmbeddedAssetChunkResponse {
  base64Data: string
}
