import { RpcClient, Subscription } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { VideoApi } from './VideoApi'

export class RpcVideoApi implements VideoApi {
  constructor(private rpcClient: RpcClient) {}

  async requestPiPAsync(input: {
    contentId: string
    videoUrl: string
    positionSeconds: number
    playbackRate?: number
    contentLabel?: string
  }): Promise<{ sessionId: string }> {
    const result = await this.rpcClient.call<{ sessionId: string }>(
      RundotGameMessageId.H5_VIDEO_REQUEST_PIP,
      input,
    )
    return result
  }

  async readyForPlaybackResumeAsync(input: {
    sessionId: string
  }): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_VIDEO_WEB_READY,
      input,
    )
  }

  async resumeAckAsync(input: { sessionId: string }): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_VIDEO_RESUME_ACK,
      input,
    )
  }

  onResumeFromNativePlayback(callback: (data: {
    sessionId: string
    positionSeconds: number
    contentId: string
  }) => void): Subscription {
    // RpcClient.onNotification delivers the PAYLOAD directly to the callback,
    // NOT an RpcNotification wrapper. So we can pass callback directly.
    return this.rpcClient.onNotification(
      RundotGameMessageId.H5_VIDEO_RESUME_FROM_NATIVE_PLAYBACK,
      callback,
    )
  }
}
