﻿import {
  NavigationApi,
  NavigationStackInfo,
  NavigateToGameOptions,
  PushAppOptions,
  QuitOptions,
} from './NavigationApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { RundotGameAPI } from '../rundot-game-api/types'

export class RpcNavigationApi implements NavigationApi {
  private readonly rundotGameApi: RundotGameAPI
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient, rundotGameApi: RundotGameAPI) {
    this.rpcClient = rpcClient
    this.rundotGameApi = rundotGameApi
  }
  async requestPopOrQuit(options?: QuitOptions): Promise<boolean> {
    const result = await this.rpcClient.call<PopOrQuitResponse>(
      RundotGameMessageId.QUIT,
      options,
    )
    return result.success
  }

  getStackInfo(): NavigationStackInfo {
    const rundotGameApi = this.rundotGameApi
    const config = window.rundotGame._config
    const stackInfo = config.context?.stack || {
      isInStack: false,
      stackPosition: 0,
      parentInstanceId: null,
      appType: 'standalone',
    }
    return stackInfo
  }

  popApp(): Promise<void> {
    const rpcClient = this.rpcClient
    return rpcClient.call(RundotGameMessageId.H5_STACK_POP_REQUEST)
  }

  pushApp(appId: string, options?: PushAppOptions): Promise<void> {
    const rpcClient = this.rpcClient
    return rpcClient.call(RundotGameMessageId.H5_STACK_PUSH_REQUEST, {
      targetAppId: appId,
      contextData: options?.contextData,
      appParams: options?.appParams,
    })
  }

  navigateToGame(targetGameId: string, options?: NavigateToGameOptions): Promise<void> {
    return this.rpcClient.call(RundotGameMessageId.H5_NAVIGATE_TO_GAME, {
      targetGameId,
      launchContext: options?.launchContext,
      returnContext: options?.returnContext,
    })
  }
}

interface PopOrQuitResponse {
  success: boolean
  action: 'popped_from_stack'
  quitReason: string
  timestamp: number
}
