import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import type { AttributionApi, CampaignParams } from './AttributionApi'

export class RpcAttributionApi implements AttributionApi {
  constructor(private readonly rpcClient: RpcClient) {}

  async getAttributionParams(): Promise<CampaignParams | null> {
    return this.rpcClient.call<CampaignParams | null>(
      RundotGameMessageId.H5_GET_ATTRIBUTION_PARAMS,
      {},
    )
  }
}
