const STORAGE_PREFIX = 'rundot_sdk_deprecation_note_'

export type DeprecationNoteDeps = {
  today: () => string
  getLastNotedDay: (key: string) => string | null
  setLastNotedDay: (key: string, day: string) => void
  warn: (message: string) => void
  recordEvent?: (eventName: string) => void
}

function defaultGetLastNotedDay(key: string): string | null {
  try {
    if (typeof localStorage === 'undefined') return null
    return localStorage.getItem(`${STORAGE_PREFIX}${key}`)
  } catch {
    return null
  }
}

function defaultSetLastNotedDay(key: string, day: string): void {
  try {
    if (typeof localStorage === 'undefined') return
    localStorage.setItem(`${STORAGE_PREFIX}${key}`, day)
  } catch {
    // ignore storage failures
  }
}

function defaultToday(): string {
  return new Date().toISOString().slice(0, 10)
}

export function noteDeprecationOncePerUtcDay(
  key: string,
  message: string,
  eventName: string,
  deps: Partial<DeprecationNoteDeps> = {},
): void {
  const today = deps.today ?? defaultToday
  const getLastNotedDay = deps.getLastNotedDay ?? defaultGetLastNotedDay
  const setLastNotedDay = deps.setLastNotedDay ?? defaultSetLastNotedDay
  const warn = deps.warn ?? ((m: string) => console.warn(m))

  const day = today()
  if (getLastNotedDay(key) === day) {
    return
  }
  setLastNotedDay(key, day)
  warn(message)
  deps.recordEvent?.(eventName)
}
