﻿import {
  NotificationsApi,
  RCSAvailabilityStatus,
  ScheduleLocalNotification,
  ScheduleNotificationOptions,
  ScheduleRCSInput,
  ScheduleRCSResult,
  RequestRCSOptInInput,
  RequestRCSOptInResult,
  SubmitMessageInput,
  SubmitMessageResult,
} from './NotificationsApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import {
  noteDeprecationOncePerUtcDay,
  type DeprecationNoteDeps,
} from './deprecationNote'

export type RpcNotificationsApiOptions = Partial<DeprecationNoteDeps> & {
  recordDeprecationEvent?: (eventName: string) => void
}

export class RpcNotificationsApi implements NotificationsApi {
  private readonly rpcClient: RpcClient
  private readonly options: RpcNotificationsApiOptions

  constructor(rpcClient: RpcClient, options: RpcNotificationsApiOptions = {}) {
    this.rpcClient = rpcClient
    this.options = options
  }

  async submitMessageAsync(input: SubmitMessageInput): Promise<SubmitMessageResult> {
    return await this.rpcClient.call<SubmitMessageResult>(
      RundotGameMessageId.MESSAGING_SUBMIT_MESSAGE,
      input,
    )
  }

  async scheduleAsync(
    title: string,
    body: string,
    seconds: number,
    notificationId?: string,
    options?: ScheduleNotificationOptions
  ): Promise<string | null> {
    noteDeprecationOncePerUtcDay(
      'schedule_async',
      'scheduleAsync is deprecated; use submitMessageAsync({ channels: ["local"], ... }) instead.',
      'sdk_deprecated_schedule_async',
      this.deprecationDeps(),
    )

    const { priority = 50, groupId, payload } = options || {}
    const result = await this.submitMessageAsync({
      channels: ['local'],
      title,
      body,
      delaySeconds: seconds,
      notificationId,
      priority,
      groupId,
      payload,
    })

    const local = result.results.find((r) => r.channel === 'local')
    if (local?.status === 'scheduled' && local.id) {
      return local.id
    }
    return null
  }

  async cancelNotification(id: string): Promise<boolean> {
    const result = await this.rpcClient.call<CancelLocalNotificationResult>(
      RundotGameMessageId.CANCEL_LOCAL_NOTIFICATION,
      {
        id: id,
      },
    )
    return result.cancelled ?? result.canceled ?? false
  }

  async getAllScheduledLocalNotifications(): Promise<
    ScheduleLocalNotification[]
  > {
    const response =
      await this.rpcClient.call<GetAllLocalNotificationsResponse>(
        RundotGameMessageId.GET_ALL_SCHEDULED_LOCAL_NOTIFICATIONS,
        {},
      )

    const notifications: ScheduleLocalNotification[] =
      response.notifications.map((notif) => {
        return {
          id: notif.identifier,
          title: notif.content.title,
          body: notif.content.body,
          payload: notif.content.data,
          trigger: notif.trigger,
        }
      })

    return notifications
  }

  async isLocalNotificationsEnabled(): Promise<boolean> {
    const response =
      await this.rpcClient.call<IsLocalNotificationsEnabledResponse>(
        RundotGameMessageId.IS_LOCAL_NOTIFICATIONS_ENABLED,
        {},
      )
    return response.enabled
  }

  async setLocalNotificationsEnabled(enabled: boolean): Promise<boolean> {
    const response =
      await this.rpcClient.call<SetLocalNotificationsEnabledResponse>(
        RundotGameMessageId.SET_LOCAL_NOTIFICATIONS_ENABLED,
        {
          enabled: enabled,
        },
      )
    return response.enabled
  }

  async getRCSAvailableAsync(): Promise<RCSAvailabilityStatus> {
    return await this.rpcClient.call<RCSAvailabilityStatus>(
      RundotGameMessageId.MESSAGING_GET_RCS_AVAILABLE,
      {},
    )
  }

  async scheduleRCSAsync(input: ScheduleRCSInput): Promise<ScheduleRCSResult> {
    noteDeprecationOncePerUtcDay(
      'schedule_rcs_async',
      'scheduleRCSAsync is deprecated; use submitMessageAsync({ channels: ["rcs"], ... }) instead.',
      'sdk_deprecated_schedule_rcs',
      this.deprecationDeps(),
    )

    const result = await this.submitMessageAsync({
      channels: ['rcs'],
      title: input.title,
      body: input.body,
      ctaUrl: input.ctaUrl,
      continuationParams: input.continuationParams,
      image: input.image,
      triggerAt: input.triggerAt,
      delaySeconds: input.delaySeconds,
    })

    const rcs = result.results.find((r) => r.channel === 'rcs')
    if (rcs?.status === 'scheduled' && rcs.id) {
      return { scheduleId: rcs.id, status: 'pending' }
    }
    if (rcs?.status === 'skipped') {
      // Benign non-schedule (not reachable, already scheduled, …) — not a
      // hard failure; legacy callers can inspect `reason`.
      return {
        scheduleId: result.messageId,
        status: 'skipped',
        ...(rcs.reason !== undefined ? { reason: rcs.reason } : {}),
      }
    }
    return { scheduleId: result.messageId, status: 'failed' }
  }

  async requestRCSOptInAsync(
    input?: RequestRCSOptInInput,
  ): Promise<RequestRCSOptInResult> {
    return await this.rpcClient.call<RequestRCSOptInResult>(
      RundotGameMessageId.MESSAGING_REQUEST_RCS_OPT_IN,
      input ?? {},
    )
  }

  private deprecationDeps(): Partial<DeprecationNoteDeps> {
    return {
      today: this.options.today,
      getLastNotedDay: this.options.getLastNotedDay,
      setLastNotedDay: this.options.setLastNotedDay,
      warn: this.options.warn,
      recordEvent: this.options.recordDeprecationEvent,
    }
  }
}

interface CancelLocalNotificationResult {
  id: string
  cancelled?: boolean
  canceled?: boolean
}

interface IsLocalNotificationsEnabledResponse {
  enabled: boolean
}

interface SetLocalNotificationsEnabledResponse {
  enabled: boolean
}

interface GetAllLocalNotificationsResponse {
  notifications: NotificationRequest[]
  count: number
}

interface NotificationRequest {
  identifier: string
  content: NotificationContent
  trigger?: import('./NotificationsApi').NotificationTriggerInput
}

export type NotificationContent = {
  title: string | null
  subtitle: string | null
  body: string | null
  data?: Record<string, unknown>
}
