import { RundotGameAPI } from '../rundot-game-api/types.ts'
import { Host } from '../Host.ts'

export * from './AdsApi.ts'
export * from './RpcAdsApi'
export * from './MockAdsApi'

// Initialize ads functionality on a RundotGameAPI instance
export function initializeAds(rundotGameApiInstance: RundotGameAPI, host: Host) {
  // Legacy
  rundotGameApiInstance.isRewardedAdReadyAsync =
    host.ads.isRewardedAdReadyAsync.bind(host.ads)
  rundotGameApiInstance.showRewardedAdAsync = host.ads.showRewardedAdAsync.bind(
    host.ads,
  )

  rundotGameApiInstance.ads = host.ads
}
