import type { AccessTier } from './AccessTier'
import type { AccessGateApi, PromptLoginResult } from './AccessGateApi'
import type { RpcClient } from '../rpc'
import type { RundotGameAPI } from '../rundot-game-api/types'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { sanitizeProfile } from './sanitizeProfile'

export class RpcAccessGateApi implements AccessGateApi {
  autoPromptLogin: boolean = true

  // Coalesces concurrent prompts: N gated calls hitting the auth wall at once
  // share one host overlay/RPC instead of stacking N login prompts.
  private inFlightLogin: Promise<PromptLoginResult> | null = null

  constructor(
    private readonly rpcClient: RpcClient,
    private readonly rundotGameApi: RundotGameAPI,
  ) {}

  getAccessTier(): AccessTier {
    const profile = this.rundotGameApi._profileData
    if (!profile || profile.isAnonymous) {
      return 'anonymous'
    }
    return 'authenticated_18plus'
  }

  isAnonymous(): boolean {
    return this.getAccessTier() === 'anonymous'
  }

  async promptLogin(): Promise<PromptLoginResult> {
    if (this.inFlightLogin) {
      return this.inFlightLogin
    }
    this.inFlightLogin = this.doPromptLogin().finally(() => {
      this.inFlightLogin = null
    })
    return this.inFlightLogin
  }

  private async doPromptLogin(): Promise<PromptLoginResult> {
    const result = await this.rpcClient.call<PromptLoginResult>(
      RundotGameMessageId.H5_PROMPT_LOGIN,
      {},
      -1,
    )

    if (result.success && result.profile) {
      this.rundotGameApi._profileData = sanitizeProfile(result.profile)
    }

    return result
  }
}
