import {
  PopupsApi,
  ShowToastOptions,
  LikeDialogResult,
  CommentsPanelResult,
  LikeStateResult,
} from './PopupsApi'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { RpcClient } from '../rpc'

// User-paced surfaces: allow up to 10 minutes before the RPC times out.
const SHOW_TIMEOUT_MS = 600_000
// Capability queries are fast; keep them snappy.
const CAN_SHOW_TIMEOUT_MS = 10_000

export class RpcPopupsApi implements PopupsApi {
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async showToast(
    message: string,
    options?: ShowToastOptions,
  ): Promise<boolean> {
    const duration = options?.duration ?? 3000
    const variant = options?.variant ?? 'info'
    const response = await this.rpcClient.call<ShowToastResponse>(
      RundotGameMessageId.TOAST,
      {
        message,
        duration,
        variant,
        action: options?.action,
      },
      duration + 2000,
    )
    return response.actionTriggered
  }

  async showLikeDialog(): Promise<LikeDialogResult> {
    return this.rpcClient.call<LikeDialogResult>(
      RundotGameMessageId.LIKE_DIALOG,
      {},
      SHOW_TIMEOUT_MS,
    )
  }

  async canShowLikeDialog(): Promise<{ available: boolean }> {
    return this.rpcClient.call<{ available: boolean }>(
      RundotGameMessageId.LIKE_DIALOG_CAN_SHOW,
      {},
      CAN_SHOW_TIMEOUT_MS,
    )
  }

  async showCommentsPanel(): Promise<CommentsPanelResult> {
    return this.rpcClient.call<CommentsPanelResult>(
      RundotGameMessageId.COMMENTS_PANEL,
      {},
      SHOW_TIMEOUT_MS,
    )
  }

  async canShowCommentsPanel(): Promise<{ available: boolean }> {
    return this.rpcClient.call<{ available: boolean }>(
      RundotGameMessageId.COMMENTS_PANEL_CAN_SHOW,
      {},
      CAN_SHOW_TIMEOUT_MS,
    )
  }

  async getLikeState(): Promise<LikeStateResult> {
    return this.rpcClient.call<LikeStateResult>(
      RundotGameMessageId.LIKE_STATE,
      {},
      CAN_SHOW_TIMEOUT_MS,
    )
  }
}

export interface ShowToastResponse {
  shown: boolean
  actionTriggered: boolean
}
