﻿import { AdsApi, ShowInterstitialAdOptions, ShowRewardedAdOptions } from './AdsApi.ts'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId.ts'

export class RpcAdsApi implements AdsApi {
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async showInterstitialAd(options?: ShowInterstitialAdOptions): Promise<boolean> {
    const response = await this.rpcClient.call<ShowInterstitialAdResponse>(
      RundotGameMessageId.SHOW_INTERSTITIAL_AD,
      options || {},
      -1,
    )
    return response.shown
  }

  async isInterstitialAdReadyAsync(): Promise<boolean> {
    const response = await this.rpcClient.call<IsInterstitialAdReadyResponse>(
      RundotGameMessageId.IS_INTERSTITIAL_AD_READY,
    )
    return response.ready
  }

  async isRewardedAdReadyAsync(): Promise<boolean> {
    const response = await this.rpcClient.call<IsRewardedAdReadyResponse>(
      RundotGameMessageId.IS_REWARDED_AD_READY,
    )
    return response.ready
  }

  async showRewardedAdAsync(options?: ShowRewardedAdOptions): Promise<boolean> {
    const result = await this.rpcClient.call<ShowRewardedAdResponse>(
      RundotGameMessageId.SHOW_REWARDED_AD,
      options || {},
      -1,
    )
    return result.rewardEarned
  }
}

interface IsRewardedAdReadyResponse {
  ready: boolean
  adType: 'rewarded'
}

interface IsInterstitialAdReadyResponse {
  ready: boolean
  adType: 'interstitial'
}

interface ShowInterstitialAdResponse {
  shown: boolean
  adType: 'interstitial'
}

interface ShowRewardedAdResponse {
  shown: boolean
  adType: string
  rewardEarned: boolean
}
