import { CollectiblesApi, CollectibleCard, VipClaimResult } from './CollectiblesApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'

/**
 * Production CollectiblesApi backed by the SDK's RPC bridge. Both methods are
 * direct RPC calls — no batching. `listCards` is typically called once on
 * game init; `claimVipCard` is a single user-initiated action.
 */
export class RpcCollectiblesApi implements CollectiblesApi {
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async listCards(): Promise<CollectibleCard[]> {
    const response = await this.rpcClient.call<{ cards: CollectibleCard[] }>(
      RundotGameMessageId.H5_COLLECTIBLES_LIST_CARDS,
      {},
    )
    return response.cards ?? []
  }

  async claimVipCard(seriesId: string, cardId: string): Promise<VipClaimResult> {
    const response = await this.rpcClient.call<VipClaimResult>(
      RundotGameMessageId.H5_COLLECTIBLES_VIP_CLAIM,
      { seriesId, cardId },
    )
    return { granted: response.granted, cardId: response.cardId }
  }
}
