﻿import { RundotGameAPI } from '../rundot-game-api/types.ts'
import { Host } from '../Host.ts'

export * from './Avatar3dApi'
export * from './Avatar3dConfig'
export * from './AssetManifest'
export * from './MockAvatarApi'
export * from './RpcAvatarApi'

export function initializeAvatar3d(rundotGameApi: RundotGameAPI, host: Host) {
  rundotGameApi.loadAvatar3dAsync = host.avatar3d.loadAvatar.bind(host.avatar3d)
  rundotGameApi.saveAvatar3dAsync = host.avatar3d.saveAvatar.bind(host.avatar3d)
  rundotGameApi.deleteAvatar3dAsync = host.avatar3d.deleteAvatar.bind(host.avatar3d)
  rundotGameApi.downloadAvatar3dManifestAsync = host.avatar3d.downloadManifest.bind(
    host.avatar3d,
  )
  rundotGameApi.showAvatar3dEditorAsync = host.avatar3d.showEditor.bind(
    host.avatar3d,
  )
  rundotGameApi.downloadAvatar3dAssetPathsAsync =
    host.avatar3d.downloadAssetPaths.bind(host.avatar3d)
}
