import { Subscription } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { GamepadReader, WebGamepadReader } from './WebGamepadReader'
import { LatencyTracker } from './LatencyTracker'
import {
  GamepadAxes,
  GamepadButtonName,
  GamepadButtonState,
  GamepadConnectionEvent,
  GamepadSnapshot,
  GamepadSource,
  GAMEPAD_BUTTON_NAMES,
  GamepadApi,
  GamepadLatencyStats,
} from './GamepadApi'

/**
 * Minimal RPC seam consumed by `RpcGamepadApi`. Structurally satisfied by the
 * SDK's `RpcClient`. `createWebGamepadReader` is an optional injection seam for
 * tests / non-browser hosts; production omits it and the real
 * `WebGamepadReader` is used.
 */
export interface GamepadRpc {
  call<T>(method: string, args?: unknown, timeoutMs?: number): Promise<T>
  onNotification<T>(id: string, callback: (payload: T) => void): Subscription
  notify(method: string, args?: unknown): void
  createWebGamepadReader?(): GamepadReader
}

export interface RpcGamepadApiOptions {
  debug?: boolean
  timeoutMs?: number
  /** Defaults to true — the handshake fires on construction (the SDK default).
   * The remote host passes `false` and calls `subscribe()` once its transport
   * is live. */
  autoSubscribe?: boolean
  /** How often (ms) the `gamepad.latency` telemetry is emitted while `debug` is on
   * (MUST-19). Off entirely when `debug` is false. */
  latencyEmitIntervalMs?: number
}

type InputMode = 'tier1' | 'tier2'

const VALID_SOURCES: readonly GamepadSource[] = [
  'web-gamepad',
  'steam-input',
  'ios-gamecontroller',
  'android-input',
]
const DEFAULT_WINDOW_SIZE = 120
const DEFAULT_HANDSHAKE_TIMEOUT_MS = 5000
const DEFAULT_LATENCY_EMIT_INTERVAL_MS = 5000
const LATENCY_EVENT = 'gamepad.latency'

function nowMs(): number {
  return typeof performance !== 'undefined' && typeof performance.now === 'function'
    ? performance.now()
    : Date.now()
}

function finiteOr(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value))
}

function integerIndex(raw: unknown): number | null {
  if (!raw || typeof raw !== 'object') return null
  const index = (raw as { index?: unknown }).index
  return typeof index === 'number' && Number.isInteger(index) ? index : null
}

function coerceButton(raw: unknown): GamepadButtonState {
  if (raw && typeof raw === 'object') {
    const button = raw as { pressed?: unknown; value?: unknown }
    const pressed = button.pressed === true
    return { pressed, value: clamp(finiteOr(button.value, pressed ? 1 : 0), 0, 1) }
  }
  return { pressed: false, value: 0 }
}

export class RpcGamepadApi implements GamepadApi {
  private supported = false
  private mode: InputMode | null = null
  private tornDown = false
  /** Set once the handshake settles to an unsupported state. */
  private serveDisabled = false

  private readonly cache = new Map<number, GamepadSnapshot>()
  private readonly lastSourceByIndex = new Map<number, GamepadSource>()
  private readonly connectedSubscribers = new Set<(event: GamepadConnectionEvent) => void>()
  private readonly disconnectedSubscribers = new Set<(event: GamepadConnectionEvent) => void>()
  private readonly notificationSubscriptions: Subscription[] = []
  private readonly latency: LatencyTracker

  private reader: GamepadReader | null = null
  private handshakePromise: Promise<void> = Promise.resolve()
  private pagehideListener: (() => void) | null = null
  private latencyEmitTimer: ReturnType<typeof setInterval> | null = null
  private readonly timeoutMs: number

  constructor(
    private readonly rpc: GamepadRpc,
    options: RpcGamepadApiOptions = {},
  ) {
    this.latency = new LatencyTracker({
      windowSize: DEFAULT_WINDOW_SIZE,
      enabled: options.debug === true,
    })
    this.timeoutMs = options.timeoutMs ?? DEFAULT_HANDSHAKE_TIMEOUT_MS

    // Field telemetry (MUST-19): only while debug is on, periodically push the
    // rolling latency stats over the SDK→host logging channel so the client
    // logs them via createDebugLogger/Datadog. Cleared on teardown (MUST-24).
    if (options.debug === true) {
      const intervalMs = options.latencyEmitIntervalMs ?? DEFAULT_LATENCY_EMIT_INTERVAL_MS
      this.latencyEmitTimer = setInterval(() => this.emitLatency(), intervalMs)
      // Don't keep a Node test process alive on the interval.
      ;(this.latencyEmitTimer as { unref?: () => void })?.unref?.()
    }

    this.notificationSubscriptions.push(
      rpc.onNotification<unknown>(RundotGameMessageId.GAMEPAD_SNAPSHOT, (p) =>
        this.handleSnapshot(p),
      ),
      rpc.onNotification<unknown>(RundotGameMessageId.GAMEPAD_CONNECTED, (p) =>
        this.handleConnected(p),
      ),
      rpc.onNotification<unknown>(RundotGameMessageId.GAMEPAD_DISCONNECTED, (p) =>
        this.handleDisconnected(p),
      ),
    )

    if (typeof window !== 'undefined') {
      this.pagehideListener = (): void => this.teardown()
      window.addEventListener('pagehide', this.pagehideListener)
    }

    if (options.autoSubscribe !== false) this.subscribe()
  }

  /** Issues the awaited `GAMEPAD_SUBSCRIBE` handshake. The host's response is the
   * sole tier authority (MUST-22/23). */
  subscribe(): Promise<void> {
    if (this.tornDown) return this.handshakePromise
    const webGamepadAvailable =
      typeof navigator !== 'undefined' &&
      typeof (navigator as Navigator).getGamepads === 'function'
    this.handshakePromise = this.rpc
      .call<unknown>(
        RundotGameMessageId.GAMEPAD_SUBSCRIBE,
        { webGamepadAvailable },
        this.timeoutMs,
      )
      .then(
        (response) => this.applyHandshake(response),
        () => this.failHandshake(),
      )
    return this.handshakePromise
  }

  /** Resolves once the handshake settles (success or failure). Never rejects. */
  ready(): Promise<void> {
    return this.handshakePromise
  }

  isSupported(): boolean {
    return this.supported && !this.tornDown
  }

  getGamepads(): GamepadSnapshot[] {
    if (this.tornDown) return []
    if (this.mode === 'tier1') return this.reader ? this.reader.read() : []
    if (this.serveDisabled) return []
    return [...this.cache.values()].filter((snapshot) => snapshot.connected)
  }

  onConnected(callback: (event: GamepadConnectionEvent) => void): Subscription {
    this.connectedSubscribers.add(callback)
    // MUST-7: pads already connected at load must still fire onConnected. The
    // reader's synthetic connects (and host connect pushes) dispatch before any
    // game subscribes — games subscribe after `await ready()` — so replay the
    // currently-connected set to this new subscriber. Empty when unsupported.
    for (const pad of this.getGamepads()) {
      callback({ index: pad.index, id: pad.id, source: pad.source })
    }
    return { unsubscribe: () => this.connectedSubscribers.delete(callback) }
  }

  onDisconnected(callback: (event: GamepadConnectionEvent) => void): Subscription {
    this.disconnectedSubscribers.add(callback)
    return { unsubscribe: () => this.disconnectedSubscribers.delete(callback) }
  }

  readonly __debug = {
    getLatencyStats: (): GamepadLatencyStats => this.latency.getStats(),
  }

  private emitLatency(): void {
    if (this.tornDown) return
    const stats = this.latency.getStats()
    if (stats.sampleCount === 0) return
    this.rpc.notify(RundotGameMessageId.DEBUG, { event: LATENCY_EVENT, ...stats })
  }

  teardown(): void {
    if (this.tornDown) return
    this.tornDown = true
    this.supported = false
    this.mode = null
    if (this.latencyEmitTimer !== null) {
      clearInterval(this.latencyEmitTimer)
      this.latencyEmitTimer = null
    }
    for (const subscription of this.notificationSubscriptions) subscription.unsubscribe()
    this.notificationSubscriptions.length = 0
    this.stopReader()
    this.cache.clear()
    this.lastSourceByIndex.clear()
    if (this.pagehideListener && typeof window !== 'undefined') {
      window.removeEventListener('pagehide', this.pagehideListener)
      this.pagehideListener = null
    }
    this.rpc.notify(RundotGameMessageId.GAMEPAD_UNSUBSCRIBE, {})
  }

  private applyHandshake(response: unknown): void {
    if (this.tornDown) return
    const mode = parseMode(response)
    if (!mode) {
      this.markUnsupported()
      return
    }
    // A re-subscribe may have left a reader from a prior Tier-1 grant; stop it
    // before (re)deciding the mode so an orphaned rAF loop can't keep firing.
    this.stopReader()
    this.supported = true
    this.mode = mode
    // A prior failed/timed-out subscribe may have latched serveDisabled; a
    // successful (re)handshake must clear it or Tier-2 would keep serving [].
    this.serveDisabled = false
    if (mode === 'tier1') {
      this.reader = this.rpc.createWebGamepadReader?.() ?? new WebGamepadReader()
      this.reader.start(
        () => {},
        (event) => this.dispatchConnected(event),
        (event) => this.dispatchDisconnected(event),
      )
    }
  }

  private failHandshake(): void {
    if (this.tornDown) return
    this.markUnsupported()
  }

  private markUnsupported(): void {
    this.supported = false
    this.mode = null
    this.serveDisabled = true
    this.cache.clear()
    this.stopReader()
  }

  private stopReader(): void {
    if (this.reader) {
      this.reader.stop()
      this.reader = null
    }
  }

  private handleSnapshot(raw: unknown): void {
    // Only cache host pushes once the handshake has granted Tier 2. Before it
    // settles `mode` is null; caching then would let getGamepads() serve pads
    // while isSupported() is still false (contract violation).
    if (this.tornDown || this.mode !== 'tier2' || this.serveDisabled) return
    const index = integerIndex(raw)
    if (index === null) return
    const snapshot = this.coerceSnapshot(raw as Record<string, unknown>, index)
    this.cache.set(index, snapshot)
    this.lastSourceByIndex.set(index, snapshot.source)
    this.latency.add(snapshot.sourceTimestamp, snapshot.deliveredTimestamp)
  }

  private handleConnected(raw: unknown): void {
    // Host pushes are Tier-2 only. Before the handshake settles `mode` is null;
    // in Tier 1 connect events come from the reader's window events, not the host.
    if (this.tornDown || this.mode !== 'tier2') return
    const index = integerIndex(raw)
    if (index === null) return
    this.dispatchConnected(this.coerceConnection(raw as Record<string, unknown>, index))
  }

  private handleDisconnected(raw: unknown): void {
    if (this.tornDown || this.mode !== 'tier2') return
    const index = integerIndex(raw)
    if (index === null) return
    // Eviction alone suffices — the host emits no snapshot for a disconnected
    // pad over the ordered channel, so no per-index blocklist is needed (MUST-21).
    this.cache.delete(index)
    this.dispatchConnection(this.disconnectedSubscribers, this.coerceConnection(raw as Record<string, unknown>, index))
  }

  private dispatchConnected(event: GamepadConnectionEvent): void {
    this.dispatchConnection(this.connectedSubscribers, event)
  }

  private dispatchDisconnected(event: GamepadConnectionEvent): void {
    this.dispatchConnection(this.disconnectedSubscribers, event)
  }

  private dispatchConnection(
    subscribers: Set<(event: GamepadConnectionEvent) => void>,
    event: GamepadConnectionEvent,
  ): void {
    for (const callback of [...subscribers]) callback(event)
  }

  private coerceSnapshot(raw: Record<string, unknown>, index: number): GamepadSnapshot {
    const buttons = {} as Record<GamepadButtonName, GamepadButtonState>
    const rawButtons =
      raw.buttons && typeof raw.buttons === 'object'
        ? (raw.buttons as Record<string, unknown>)
        : {}
    for (const name of GAMEPAD_BUTTON_NAMES) buttons[name] = coerceButton(rawButtons[name])

    const rawAxes =
      raw.axes && typeof raw.axes === 'object' ? (raw.axes as Record<string, unknown>) : {}
    const axes: GamepadAxes = {
      leftX: clamp(finiteOr(rawAxes.leftX, 0), -1, 1),
      leftY: clamp(finiteOr(rawAxes.leftY, 0), -1, 1),
      rightX: clamp(finiteOr(rawAxes.rightX, 0), -1, 1),
      rightY: clamp(finiteOr(rawAxes.rightY, 0), -1, 1),
    }

    return {
      index,
      id: typeof raw.id === 'string' ? raw.id : '',
      connected: raw.connected === true,
      source: this.resolveSource(raw.source, index),
      standardMapping: raw.standardMapping === true,
      buttons,
      axes,
      sourceTimestamp: finiteOr(raw.sourceTimestamp, nowMs()),
      deliveredTimestamp: finiteOr(raw.deliveredTimestamp, nowMs()),
    }
  }

  private coerceConnection(raw: Record<string, unknown>, index: number): GamepadConnectionEvent {
    return {
      index,
      id: typeof raw.id === 'string' ? raw.id : '',
      source: this.resolveSource(raw.source, index),
    }
  }

  /** Tier 2 spans multiple providers; trust the host's stamped source, else
   * reuse the last valid source for this index, else any cached pad's source,
   * else an explicitly-arbitrary guard (MUST-26). */
  private resolveSource(rawSource: unknown, index: number): GamepadSource {
    if (typeof rawSource === 'string' && (VALID_SOURCES as readonly string[]).includes(rawSource)) {
      return rawSource as GamepadSource
    }
    const lastForIndex = this.lastSourceByIndex.get(index)
    if (lastForIndex) return lastForIndex
    const anyCached = this.cache.values().next().value
    if (anyCached) return anyCached.source
    return 'steam-input'
  }
}

function parseMode(response: unknown): InputMode | null {
  if (!response || typeof response !== 'object') return null
  const typed = response as { supported?: unknown; mode?: unknown }
  if (typed.supported !== true) return null
  if (typed.mode === 'tier1' || typed.mode === 'tier2') return typed.mode
  return null
}
