﻿import { RundotGameAPI } from '../rundot-game-api/types'
import { Host } from '../Host'

export * from './HapticsApi'
export * from './RpcHapticsApi'
export * from './MockHapticsApi'

export function initializeHaptics(rundotGameApi: RundotGameAPI, host: Host) {
  rundotGameApi.triggerHapticAsync = (style) => {
    return host.haptics.triggerHapticAsync(style)
  }
}
