﻿import { BaseCdnApi } from './BaseCdnApi'
import { FetchFromCdnOptions, AssetUrlResult } from './CdnApi'
import {
  parseCdnLocationFromWindow,
  CdnUrlShape,
  ParsedCdnLocation,
} from './cdn-url-utils'
import { RpcClient } from '../rpc/RpcClient'
import { RundotGameMessageId } from '../RundotGameMessageId'

/**
 * Internal interface for the CDN manifest file structure.
 * Maps logical asset paths to their hashed filenames.
 * Supports both v1 (string hash) and v2 (object with protected flag).
 */
interface CdnManifest {
  version: number,
  hashAlgorithm: string,
  files: Record<string, string | { hash: string; protected?: boolean }>
}

/**
 * CDN API implementation for production/remote environments.
 * Automatically derives the CDN URL from the current window location.
 * Uses RPC to delegate URL resolution to the Client App, with legacy fallback.
 */
export class HostCdnApi extends BaseCdnApi {
  private static readonly CDN_FOLDER_NAME = 'cdn-assets'
  private static readonly MANIFEST_FILE_PREFIX = 'manifest_'
  private static readonly SHARED_ASSETS_CDN_BASE = 'https://venus-static-01293ak.web.app'

  private readonly bucketBaseUrl: string // Bucket root URL (CDN root)
  private readonly gameId: string // Current game ID
  private readonly version: string // Current game version
  private readonly shape: CdnUrlShape // URL shape this instance was constructed from
  private readonly rpcClient: RpcClient
  private manifestCache: CdnManifest | null = null
  private manifestPromise: Promise<CdnManifest> | null = null

  constructor(rpcClient: RpcClient) {
    super()
    this.rpcClient = rpcClient
    const { bucketBaseUrl, gameId, version, shape } = this.computeCdnInfo()
    this.bucketBaseUrl = this.normalizeBaseUrl(bucketBaseUrl)
    this.gameId = gameId
    this.version = version
    this.shape = shape
  }

  protected getCdnAssetsBaseUrl(): string {
    // Per-app shape: the host already scopes us to <gameId>, so the
    // cdn-assets folder hangs directly off the bucket root. The shim
    // prepends `<env>/<gameId>/` server-side.
    //
    // Legacy shape: gameId is a path segment under the shared bucket,
    // so it must be included explicitly.
    if (this.shape === 'per-app') {
      return `${this.bucketBaseUrl}/${HostCdnApi.CDN_FOLDER_NAME}`
    }
    return `${this.bucketBaseUrl}/${this.gameId}/${HostCdnApi.CDN_FOLDER_NAME}`
  }

  protected getCdnBaseUrl(): string {
    // Return the bucket root URL for shared assets (avatar3d, libs)
    return this.bucketBaseUrl
  }

  protected getSharedAssetsCdnBaseUrl(): string {
    // Return hardcoded CDN URL for shared assets (avatar3d, libs)
    return HostCdnApi.SHARED_ASSETS_CDN_BASE
  }

  /**
   * Compute CDN information from the current window location.
   *
   * Accepts both supported URL shapes — see `parseCdnLocationFromUrl` in
   * cdn-url-utils for the layouts. The shape discriminator is propagated
   * to {@link getCdnAssetsBaseUrl}.
   *
   * @throws {Error} If not in browser environment or URL structure doesn't match either expected shape
   */
  private computeCdnInfo(): ParsedCdnLocation {
    if (typeof window === 'undefined') {
      throw new Error(
        '[RUN] Cannot construct CDN URL: window is undefined (not in browser environment)'
      )
    }

    const location = parseCdnLocationFromWindow()
    if (location === null) {
      throw new Error(
        `[RUN] Cannot construct CDN URL: location matches neither per-app subdomain ` +
        `(<gameId>.h5-apps.<env>.getreel.com/<version>/...) nor legacy single-host ` +
        `(/{bucket}/{gameId}/{version}/...). Got: ${window.location.href}`
      )
    }

    return location
  }

  /**
   * Fetch directly from CDN root (bucket root).
   * This is the primitive fetch operation that accesses files from the bucket base URL.
   *
   * @param subPath - Path relative to bucket root (e.g., "othergame/bundle.stow", "game123/cdn-assets/file.png")
   * @param options - Optional fetch options including timeout
   * @returns Promise<Blob> - The asset data as a Blob
   *
   * @example
   * // App URL: https://h5-apps.dev.com/development/game123/v1.0.0/
   * // fetchFromCdn("othergame/asset.png")
   * // → https://h5-apps.dev.com/development/othergame/asset.png
   */
  async fetchFromCdn(subPath: string, options?: FetchFromCdnOptions): Promise<Blob> {
    const url = this.buildCdnUrl(subPath, this.bucketBaseUrl)
    return this.executeFetch(url, options)
  }

  /**
   * Resolve a logical asset path to its actual CDN URL.
   * Uses RPC to delegate resolution to the Client App (which handles entitlements
   * and signed URLs). Falls back to legacy manifest-based resolution if the
   * Client App doesn't have the CDN handler.
   */
  async resolveAssetUrl(subPath: string): Promise<string> {
    const normalizedPath = this.cleanSubPath(subPath)
    try {
      const response = await this.rpcClient.call<{ url: string }>(
        RundotGameMessageId.H5_CDN_RESOLVE_ASSET_URL,
        { assetPath: normalizedPath },
      )
      return response.url
    } catch (error) {
      // Fallback to legacy path if Client App doesn't have the CDN handler
      if (this.isUnsupportedMessageError(error)) {
        return this.legacyResolveAssetUrl(normalizedPath)
      }
      throw error
    }
  }

  /**
   * Batch resolve multiple asset paths to their CDN URLs.
   * Returns per-path results — a missing entitlement on one path does not fail the batch.
   */
  async resolveAssetUrls(subPaths: string[]): Promise<AssetUrlResult[]> {
    const normalizedPaths = subPaths.map(p => this.cleanSubPath(p))
    try {
      const response = await this.rpcClient.call<{ results: AssetUrlResult[] }>(
        RundotGameMessageId.H5_CDN_RESOLVE_ASSET_URLS,
        { assetPaths: normalizedPaths },
      )
      return response.results
    } catch (error) {
      if (this.isUnsupportedMessageError(error)) {
        return this.legacyResolveAssetUrls(subPaths, normalizedPaths)
      }
      throw error
    }
  }

  /**
   * Refresh the Client App's entitlement cache.
   * Call after a purchase or reward grant so newly acquired entitlements take effect.
   */
  async refreshEntitlements(): Promise<void> {
    try {
      await this.rpcClient.call(
        RundotGameMessageId.H5_CDN_REFRESH_ENTITLEMENTS,
        {},
      )
    } catch (error) {
      if (this.isUnsupportedMessageError(error)) {
        // No-op for legacy clients — no entitlement cache to refresh
        return
      }
      throw error
    }
  }

  /**
   * Legacy fallback — fetches manifest directly and builds public URL.
   * Only works for public assets. Protected assets throw a clear error.
   */
  private async legacyResolveAssetUrl(normalizedPath: string): Promise<string> {
    const manifest = await this.getManifestLegacy()
    const entry = manifest.files[normalizedPath]
    if (!entry) {
      throw new Error(
        `[RUN] Asset not found in manifest: ${normalizedPath}. ` +
          `Available paths: ${Object.keys(manifest.files).join(', ')}`,
      )
    }

    const hash = typeof entry === 'string' ? entry : entry.hash
    const isProtected = typeof entry === 'object' && entry.protected === true

    if (isProtected) {
      throw new Error(
        `[RUN] Asset "${normalizedPath}" requires entitlement validation. ` +
        `Update the Client App to a version that supports CDN entitlements.`,
      )
    }

    const extensionMatch = normalizedPath.match(/\.([^.]+)$/)
    const extension = extensionMatch ? extensionMatch[1] : ''
    const actualFilename = extension ? `${hash}.${extension}` : hash
    return this.buildCdnUrl(actualFilename, this.getCdnAssetsBaseUrl())
  }

  private async legacyResolveAssetUrls(originalPaths: string[], normalizedPaths: string[]): Promise<AssetUrlResult[]> {
    return Promise.all(
      normalizedPaths.map(async (p, i) => {
        try {
          const url = await this.legacyResolveAssetUrl(p)
          return { path: originalPaths[i], status: 'ok' as const, url }
        } catch (error) {
          const isEntitlementError = error instanceof Error && error.message.includes('requires entitlement validation')
          return {
            path: originalPaths[i],
            status: 'error' as const,
            error: isEntitlementError ? 'ENTITLEMENT_REQUIRED' : 'ASSET_NOT_FOUND',
          }
        }
      })
    )
  }

  private isUnsupportedMessageError(error: unknown): boolean {
    if (error instanceof Error) {
      return error.message.includes('Unsupported message type')
    }
    if (typeof error === 'object' && error !== null && 'error' in error) {
      return String((error as any).error).includes('Unsupported message type')
    }
    return false
  }

  /**
   * Fetch an asset using the manifest to resolve the actual hashed filename.
   *
   * @param relativePath - The logical path to the asset (e.g., "/assets/sample.json" or "assets/sample.json")
   * @param options - Optional fetch options including timeout
   * @returns Promise<Blob> - The asset data as a Blob
   * @throws {Error} If the asset is not found in the manifest or the fetch fails
   */
  async fetchAsset(relativePath: string, options?: FetchFromCdnOptions): Promise<Blob> {
    const resolvedUrl = await this.resolveAssetUrl(relativePath)
    return this.executeFetch(resolvedUrl, options)
  }

  /**
   * Get the manifest (legacy fallback), either from cache or by fetching it.
   * Uses promise caching to prevent multiple simultaneous fetches.
   */
  private async getManifestLegacy(): Promise<CdnManifest> {
    // Return cached manifest if available
    if (this.manifestCache) {
      return this.manifestCache
    }

    // If a fetch is in progress, wait for it
    if (this.manifestPromise) {
      return this.manifestPromise
    }

    // Start fetching the manifest
    this.manifestPromise = this.fetchManifestLegacy()

    try {
      const manifest = await this.manifestPromise
      this.manifestCache = manifest
      return manifest
    } finally {
      this.manifestPromise = null
    }
  }

  /**
   * Fetch the manifest file from the CDN (legacy fallback).
   * The manifest filename is based on the version: manifest_{version}.json
   */
  private async fetchManifestLegacy(): Promise<CdnManifest> {
    const manifestFilename = `${HostCdnApi.MANIFEST_FILE_PREFIX}${this.version}.json`
    // Legacy manifests live in cdn-assets/ (no version segment)
    const manifestUrl = this.buildCdnUrl(manifestFilename, this.getCdnAssetsBaseUrl())

    try {
      const response = await fetch(manifestUrl, {
        method: 'GET',
        headers: {
          Accept: 'application/json',
        },
        mode: 'cors',
        cache: 'default',
      })

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`)
      }

      const manifest = await response.json() as CdnManifest

      // Validate manifest structure
      if (!manifest.files || typeof manifest.files !== 'object') {
        throw new Error(
          'Invalid manifest structure: missing or invalid "files" property',
        )
      }

      return manifest
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      throw new Error(
        `[RUN] Failed to fetch CDN manifest (${manifestFilename}): ${message}`
      )
    }
  }
}
