import { RpcClient } from '../rpc'
import { StorageApi } from './StorageApi.ts'
import { MethodIds } from './RpcStorageApi.ts'

/**
 * Method IDs for the legacy global-storage fallback. Mirrors `MethodIds` minus
 * `getAllData` — the legacy host only exposes `getAllItems`, which returns a
 * `Record<string, string>` (the data) rather than just keys.
 */
export interface LegacyGlobalMethodIds {
  clear: string
  getItem: string
  getKey: string
  length: string
  removeItem: string
  setItem: string
  getAllItems: string
  setMultipleItems: string
  removeMultipleItems: string
}

/**
 * SharedStorage handle that fires both the M3 `SHARED_STORAGE_*` family and
 * the legacy `GLOBAL_STORAGE_*` family on every operation. Whichever family
 * the host registers handlers for wins; the other returns synchronously with
 * an "Unsupported message type" error which we suppress.
 *
 * Scope `(targetAppId, namespace, sourceAppId)` is dropped on the legacy
 * wire — the legacy host only knows a flat per-user namespace. Two games
 * writing the same raw key on a legacy host will collide; this is a known
 * trade-off for the transition window. See the migration plan for details.
 */
export class DualEmitStorageApi implements StorageApi {
  constructor(
    private readonly rpcClient: RpcClient,
    private readonly sharedIds: MethodIds,
    private readonly sharedScope: { targetAppId?: string; namespace: string },
    private readonly globalIds: LegacyGlobalMethodIds,
  ) {}

  private sharedBody(extra?: Record<string, unknown>): Record<string, unknown> {
    const { targetAppId, namespace } = this.sharedScope
    const body: Record<string, unknown> = { namespace, ...(extra ?? {}) }
    if (targetAppId !== undefined) body.targetAppId = targetAppId
    return body
  }

  clear(): Promise<void> {
    // On a legacy host this nukes the flat per-user doc, including data
    // written by other games' sharedStorage scopes. Accepted trade-off
    // for the transition window.
    return dualWrite(
      this.rpcClient.call(this.sharedIds.clear, this.sharedBody()),
      this.rpcClient.call(this.globalIds.clear, undefined),
    )
  }

  getItem(key: string): Promise<string | null> {
    return dualRead(
      this.rpcClient.call<string | null>(this.sharedIds.getItem, this.sharedBody({ key })),
      this.rpcClient.call<string | null>(this.globalIds.getItem, { key }),
    )
  }

  setItem(key: string, value: string): Promise<void> {
    return dualWrite(
      this.rpcClient.call(this.sharedIds.setItem, this.sharedBody({ key, value })),
      this.rpcClient.call(this.globalIds.setItem, { key, value }),
    )
  }

  key(index: number): Promise<string | null> {
    return dualRead(
      this.rpcClient.call<string | null>(this.sharedIds.getKey, this.sharedBody({ index })),
      this.rpcClient.call<string | null>(this.globalIds.getKey, { index }),
    )
  }

  length(): Promise<number> {
    return dualRead(
      this.rpcClient.call<number>(this.sharedIds.length, this.sharedBody()),
      this.rpcClient.call<number>(this.globalIds.length, undefined),
    )
  }

  removeItem(key: string): Promise<void> {
    return dualWrite(
      this.rpcClient.call(this.sharedIds.removeItem, this.sharedBody({ key })),
      this.rpcClient.call(this.globalIds.removeItem, { key }),
    )
  }

  removeMultipleItems(keys: string[]): Promise<void> {
    if (!this.sharedIds.removeMultipleItems) {
      throw new Error('Method not implemented')
    }
    return dualWrite(
      this.rpcClient.call(this.sharedIds.removeMultipleItems, this.sharedBody({ keys })),
      this.rpcClient.call(this.globalIds.removeMultipleItems, { keys }),
    )
  }

  getAllItems(): Promise<string[]> {
    if (!this.sharedIds.getAllItems) {
      throw new Error('Method not implemented')
    }
    // Legacy `GLOBAL_STORAGE_GET_ALL_ITEMS` returns the full data dict, not a
    // key list — convert before racing.
    const sharedCall = this.rpcClient.call<string[]>(
      this.sharedIds.getAllItems,
      this.sharedBody(),
    )
    const globalCall = this.rpcClient
      .call<Record<string, string>>(this.globalIds.getAllItems, undefined)
      .then((dict) => Object.keys(dict ?? {}))
    return dualRead(sharedCall, globalCall)
  }

  getAllData(): Promise<Record<string, string>> {
    if (!this.sharedIds.getAllData) {
      throw new Error('Method not implemented')
    }
    return dualRead(
      this.rpcClient.call<Record<string, string>>(this.sharedIds.getAllData, this.sharedBody()),
      this.rpcClient.call<Record<string, string>>(this.globalIds.getAllItems, undefined),
    )
  }

  setMultipleItems(items: { key: string; value: string }[]): Promise<void> {
    if (!this.sharedIds.setMultipleItems) {
      throw new Error('Method not implemented')
    }
    return dualWrite(
      this.rpcClient.call(this.sharedIds.setMultipleItems, this.sharedBody({ items })),
      this.rpcClient.call(this.globalIds.setMultipleItems, { items }),
    )
  }
}

/**
 * The host returns this exact prefix synchronously when a message ID has no
 * handler registered. Used to distinguish "this host version doesn't support
 * the API" from a real error we should propagate.
 */
const NO_HANDLER_PREFIX = 'Unsupported message type:'

function isNoHandlerError(reason: unknown): boolean {
  return reason instanceof Error && reason.message.startsWith(NO_HANDLER_PREFIX)
}

/**
 * Fire both write paths. Succeed if at least one fulfills. If both reject,
 * surface a real error before falling back to a no-handler error so callers
 * see meaningful failures (quota, network) rather than the suppressed
 * legacy-routing signal.
 */
async function dualWrite(
  primary: Promise<unknown>,
  fallback: Promise<unknown>,
): Promise<void> {
  const results = await Promise.allSettled([primary, fallback])
  if (results.some((r) => r.status === 'fulfilled')) return
  const realError = results.find(
    (r): r is PromiseRejectedResult =>
      r.status === 'rejected' && !isNoHandlerError(r.reason),
  )
  if (realError) throw realError.reason
  throw (results[0] as PromiseRejectedResult).reason
}

/**
 * Fire both read paths. Return whichever fulfills first; if both reject,
 * surface a real error before a no-handler error.
 */
async function dualRead<T>(primary: Promise<T>, fallback: Promise<T>): Promise<T> {
  const results = await Promise.allSettled([primary, fallback])
  for (const r of results) {
    if (r.status === 'fulfilled') return r.value
  }
  for (const r of results) {
    if (r.status === 'rejected' && !isNoHandlerError(r.reason)) {
      throw r.reason
    }
  }
  throw (results[0] as PromiseRejectedResult).reason
}
