import { EnvironmentApi, EnvironmentInfo } from './EnvironmentApi'
import { RundotGameAPI } from '../rundot-game-api/types'

export class HostEnvironmentApi implements EnvironmentApi {
  private readonly rundotGameApi: RundotGameAPI

  constructor(rundotGameApi: RundotGameAPI) {
    this.rundotGameApi = rundotGameApi
  }

  getEnvironment(): EnvironmentInfo {
    const environment = this.rundotGameApi._environmentData

    if (!environment) {
      throw new Error(
        '[RUN] Environment info not available. You must await RundotGameAPI.initializeAsync() before calling getEnvironment(). INIT_SDK has not completed.',
      )
    }

    // A host that predates these fields omits them on the wire; each missing
    // capability defaults to true and the Steam flags to false, preserving
    // older host behavior.
    //
    // `subscriptions` is special: hosts from before the purchases/subscriptions
    // split used a single `purchases` flag to govern ALL purchases (including
    // subscriptions), so a Steam-era host sent `purchases: false` with no
    // `subscriptions`. Defaulting `subscriptions` to the legacy `purchases`
    // value (then true) prevents a new-SDK game from showing subscription upsell
    // inside such a host while its checkout stays blocked.
    return {
      ...environment,
      capabilities: {
        ads: environment.capabilities?.ads ?? true,
        purchases: environment.capabilities?.purchases ?? true,
        subscriptions:
          environment.capabilities?.subscriptions ??
          environment.capabilities?.purchases ??
          true,
      },
      isSteamDesktop: environment.isSteamDesktop ?? false,
      isSteamDeck: environment.isSteamDeck ?? false,
    }
  }
}
