﻿import { Avatar3dApi, Avatar3dEdits, ShowEditorOptions } from './Avatar3dApi.ts'
import { Avatar3dConfig } from './Avatar3dConfig.ts'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId.ts'
import { Asset, AssetManifest } from './AssetManifest.ts'
import { RundotGameAPI } from '../rundot-game-api/types.ts'

export class RpcAvatarApi implements Avatar3dApi {
  private readonly rundotGameApi: RundotGameAPI
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient, rundotGameApi: RundotGameAPI) {
    this.rpcClient = rpcClient
    this.rundotGameApi = rundotGameApi
  }

  async downloadAssetPaths(): Promise<Record<string, string[]>> {
    const rundotGameApi = this.rundotGameApi

    const manifestUrl = rundotGameApi.cdn.resolveAvatarAssetUrl('assets.json')

    const manifest = await this.fetchFromCdn(manifestUrl)

    const categories = manifest.categories || {}

    // Process into asset paths with full URLs
    const assetPaths: Record<string, string[]> = {}
    for (const categoryKey in categories) {
      const categoryData = categories[categoryKey]
      const categoryPath = categoryKey
      const assetUrls = (categoryData?.assets || []).map((asset: Asset) => {
        const url = rundotGameApi.cdn.resolveAvatarAssetUrl(
          categoryPath + '/' + asset.filename,
        )
        return url
      })
      assetPaths[categoryKey] = assetUrls
    }

    // Return direct asset paths
    return assetPaths
  }

  async downloadManifest(): Promise<AssetManifest> {
    const rundotGameApi = this.rundotGameApi

    // Use shared CDN fetch utility
    const manifestUrl = rundotGameApi.cdn.resolveAvatarAssetUrl('assets.json')
    const manifest = await this.fetchFromCdn(manifestUrl)

    // Return direct manifest
    return manifest
  }

  async loadAvatar(avatarId?: string): Promise<Avatar3dConfig | null> {
    const result = await this.rpcClient.call(RundotGameMessageId.AVATAR3D_LOAD, {
      avatar3dId: avatarId,
    })
    return result as Avatar3dConfig
  }

  saveAvatar(config: Avatar3dConfig): Promise<string> {
    return this.rpcClient.call(RundotGameMessageId.AVATAR3D_SAVE, {
      config: config,
    })
  }

  deleteAvatar(): Promise<void> {
    return this.rpcClient.call(RundotGameMessageId.AVATAR3D_DELETE)
  }

  async showEditor(options?: ShowEditorOptions): Promise<Avatar3dEdits> {
    const rpcClient = this.rpcClient

    // Use _sendRequest to get the final result when the editor closes
    const rawResult = await rpcClient.call<Avatar3dEdits>(
      RundotGameMessageId.H5_STACK_PUSH_REQUEST,
      {
        targetAppId: 'AVATAR3D',
        contextData: options?.contextData || {},
        appParams: {
          currentAvatar: options?.currentAvatar,
          onSave: options?.onSave,
          onCancel: options?.onCancel,
        },
      },
    )

    // Return direct editor result
    return {
      wasChanged: rawResult.wasChanged || false,
      config: rawResult.config || null,
      savedAvatarId: rawResult.savedAvatarId || null,
    }
  }

  private async fetchFromCdn(url: string): Promise<AssetManifest> {
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        Accept: 'application/json, text/plain, */*',
        'Content-Type': 'application/json',
      },
      mode: 'cors',
      cache: 'no-cache',
    })

    if (!response.ok) {
      throw new Error(
        `CDN fetch failed: ${response.status} ${response.statusText}`,
      )
    }

    return (await response.json()) as AssetManifest
  }

}
