﻿import { RundotGameAPI } from '../rundot-game-api/types.ts'
import { Host } from '../Host.ts'

export * from './StorageApi'
export * from './MockStorageApi'
export * from './RpcStorageApi'
export * from './DualEmitStorageApi'
export * from './RpcInboundStorageApi'
// FirestoreStorageApi is intentionally NOT exported here.
// It depends on Firebase and should only be imported by PlaygroundHost via direct import.
// This prevents Firebase from being bundled in production builds.

export function initializeStorage(rundotGameApiInstance: RundotGameAPI, host: Host) {
  rundotGameApiInstance.deviceCache = host.deviceCache
  rundotGameApiInstance.appStorage = host.appStorage
  rundotGameApiInstance.ownerStorage = host.ownerStorage
  rundotGameApiInstance.sharedStorage = host.sharedStorage
}
