﻿import { Experiment, FeaturesApi } from './FeaturesApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'

export class RpcFeaturesApi implements FeaturesApi {
  private readonly rpcClient: RpcClient

  constructor(rcpClient: RpcClient) {
    this.rpcClient = rcpClient
  }

  async getExperiment(experimentName: string): Promise<Experiment | null> {
    return await this.rpcClient.call(RundotGameMessageId.GET_EXPERIMENT, {
      experimentName: experimentName,
    })
  }

  async getFeatureFlag(flagName: string): Promise<boolean> {
    return await this.rpcClient.call(RundotGameMessageId.GET_FEATURE_FLAG, {
      flagName: flagName,
    })
  }

  async getFeatureGate(gateName: string): Promise<boolean> {
    return await this.rpcClient.call(RundotGameMessageId.GET_FEATURE_GATE, {
      gateName: gateName,
    })
  }
}
