﻿import { AnalyticsApi } from './AnalyticsApi.ts'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId.ts'

export class RpcAnalyticsApi implements AnalyticsApi {
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async recordCustomEvent(
    eventName: string,
    payload: Record<string, any>,
  ): Promise<void> {
    // Fire-and-forget: analytics should never block gameplay or cause fatal errors.
    // The host may not respond in time (e.g. device sleep, throttled background
    // tab). Use notify() so no timeout is armed and no log spam occurs.
    this.rpcClient.notify(RundotGameMessageId.LOG_ANALYTICS_EVENT, {
      eventName: eventName,
      params: payload,
    })
  }

  async trackFunnelStep(stepNumber: number, stepName: string, funnelName?: string, funnelOrder?: number): Promise<void> {
    // Fire-and-forget: analytics should never block gameplay or cause fatal errors.
    this.rpcClient.notify(RundotGameMessageId.TRACK_FUNNEL_STEP, {
      stepNumber,
      stepName,
      funnelName,
      funnelOrder,
    })
  }
}
