﻿import { Host } from '../Host'
import { RundotGameAPI } from '../rundot-game-api/types'

export * from './LoggingApi'
export * from './MockLoggingApi'
export * from './RpcLoggingApi'

export function initializeLoggingApi(rundotGameApi: RundotGameAPI, host: Host): void {
  rundotGameApi.log = (message, ...args: any[]) => {
    return host.logging.logDebug(message, ...args)
  }

  rundotGameApi.error = (message, ...args: any[]) => {
    return host.logging.logError(message, ...args)
  }
}
