﻿import { ProfileApi } from './ProfileApi'
import { Profile } from '../rundot-game-api/types'
import { RundotGameAPI } from '../rundot-game-api/types'

export class HostProfileApi implements ProfileApi {
  private readonly rundotGameApi: RundotGameAPI

  constructor(rundotGameApi: RundotGameAPI) {
    this.rundotGameApi = rundotGameApi
  }

  getCurrentProfile(): Profile {
    const profile = this.rundotGameApi._profileData
    
    if (!profile) {
      throw new Error(
        '[RUN] Profile not available. You must await RundotGameAPI.initializeAsync() before calling getProfile(). INIT_SDK has not completed.',
      )
    }

    // Profile is already sanitized by RemoteHost.initialize()
    // Validate required fields
    if (!profile.id || !profile.username) {
      throw new Error(
        '[RUN] INIT_SDK returned an incomplete profile (missing id/username). The host must supply valid profile data.',
      )
    }

    return {
      id: profile.id,
      username: profile.username,
      avatarUrl: profile.avatarUrl,
      isAnonymous: profile.isAnonymous,
    }
  }
}
