import {
  RoomDataUpdate,
  RoomMessageEvent,
  ProposedMoveEvent,
} from './RoomsApi'
import { RundotGameTransport, RundotGameMessage } from '../RundotGameTransport'
import { Subscription } from '../rpc'

// Subscription state management shared between RoomsApi and notification routing
export interface RoomNotificationSubscriptionState {
  data: Record<string, Array<(event: RoomDataUpdate) => void>>
  messages: Record<string, Array<(event: RoomMessageEvent) => void>>
  gameEvents: Record<string, Array<(event: ProposedMoveEvent) => void>>
}

/**
 * Invoke callbacks with error handling. Logs and rethrows to fail loudly.
 */
function invokeCallbacks<T>(
  callbacks: Array<(event: T) => void>,
  event: T,
  context: string,
): void {
  callbacks.forEach((callback) => {
    try {
      callback(event)
    } catch (error) {
      console.error(`[RUN] Error in ${context} callback:`, error)
      throw error
    }
  })
}

// Raw payloads delivered through the transport channel (without 'type' field)
type RawRoomDataNotification = Omit<RoomDataUpdate, 'type'>
type RawRoomMessageNotification = Omit<RoomMessageEvent, 'type'>
type RawProposedMoveNotification = Omit<ProposedMoveEvent, 'type'>

/**
 * Set up room notification listeners using the transport's onRundotGameMessage hook.
 * This routes host-sent room notifications (H5_ROOM_DATA_UPDATED, etc.) to the
 * callbacks registered in the RoomsApi instance.
 * @param transport The RUN.world transport to listen for messages
 * @param getSubscriptions Function to retrieve subscription state from RoomsApi
 */
export function setupRoomNotifications(
  transport: RundotGameTransport,
  getSubscriptions: () => RoomNotificationSubscriptionState,
): Subscription {
  return transport.onRundotGameMessage((message: RundotGameMessage) => {
    const subscriptions = getSubscriptions()
    if (!subscriptions) {
      return
    }

    // Route H5_ROOM_DATA_UPDATED notifications to data callbacks
    if (message.type === 'H5_ROOM_DATA_UPDATED') {
      const messageData = message.data as RawRoomDataNotification
      const { roomId, roomData } = messageData
      if (!roomId) return

      const callbacks = subscriptions.data[roomId] || []
      const event: RoomDataUpdate = {
        type: 'H5_ROOM_DATA_UPDATED',
        roomId,
        roomData,
        timestamp: messageData.timestamp,
      }

      invokeCallbacks(callbacks, event, 'room data')
    }

    // Route H5_ROOM_MESSAGE_* notifications to message callbacks
    if (
      message.type === 'H5_ROOM_MESSAGE_RECEIVED' ||
      message.type === 'H5_ROOM_MESSAGE_UPDATED' ||
      message.type === 'H5_ROOM_MESSAGE_DELETED'
    ) {
      const messageData = message.data as RawRoomMessageNotification
      const { roomId } = messageData
      if (!roomId) return

      const callbacks = subscriptions.messages[roomId] || []
      const event: RoomMessageEvent = {
        type: message.type as RoomMessageEvent['type'],
        roomId,
        message: messageData.message,
        timestamp: messageData.timestamp,
      }

      invokeCallbacks(callbacks, event, 'room message')
    }

    // Route H5_PROPOSED_MOVE_VALIDATION_UPDATED to game event callbacks
    if (message.type === 'app:h5:proposedMoveValidationUpdated') {
      const messageData = message.data as RawProposedMoveNotification
      const { roomId } = messageData
      if (!roomId) return

      const callbacks = subscriptions.gameEvents[roomId] || []
      const event: ProposedMoveEvent = {
        type: 'app:h5:proposedMoveValidationUpdated',
        roomId,
        proposedMoveData: messageData.proposedMoveData,
        proposedMoveId: messageData.proposedMoveId,
        changeType: messageData.changeType,
        timestamp: messageData.timestamp,
      }

      invokeCallbacks(callbacks, event, 'game event')
    }
  })
}

