import { DeviceApi, DeviceInfo } from './DeviceApi'
import { RundotGameAPI } from '../rundot-game-api/types'

export class HostDeviceApi implements DeviceApi {
  private readonly rundotGameApi: RundotGameAPI

  constructor(rundotGameApi: RundotGameAPI) {
    this.rundotGameApi = rundotGameApi
  }

  getDevice(): DeviceInfo {
    const device = this.rundotGameApi._deviceData
    
    if (!device) {
      throw new Error(
        '[RUN] Device info not available. You must await RundotGameAPI.initializeAsync() before calling getDevice(). INIT_SDK has not completed.',
      )
    }

    return device
  }
}

