﻿import {
  AwakeCallback,
  BackButtonCallback,
  IdentityChangedCallback,
  LifecycleApi,
  PauseCallback,
  QuitCallback,
  ResumeCallback,
  SleepCallback,
} from './LifecycleApi'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { RpcClient, Subscription } from '../rpc'

export class RpcLifecycleApi implements LifecycleApi {
  private readonly rpcClient: RpcClient
  private backButtonHandlerRegistered = false

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  onQuit(callback: QuitCallback): Subscription {
    return this.rpcClient.onNotification(RundotGameMessageId.QUIT, callback)
  }

  onSleep(callback: SleepCallback): Subscription {
    return this.rpcClient.onNotification(RundotGameMessageId.SLEEP, callback)
  }

  onAwake(callback: AwakeCallback): Subscription {
    return this.rpcClient.onNotification(RundotGameMessageId.AWAKE, callback)
  }

  onResume(callback: ResumeCallback): Subscription {
    return this.rpcClient.onNotification(RundotGameMessageId.RESUME, callback)
  }

  onPause(callback: PauseCallback): Subscription {
    return this.rpcClient.onNotification(RundotGameMessageId.PAUSE, callback)
  }

  onIdentityChanged(callback: IdentityChangedCallback): Subscription {
    return this.rpcClient.onNotification(
      RundotGameMessageId.IDENTITY_CHANGED,
      callback,
    )
  }

  onBackButton(callback: BackButtonCallback): Subscription {
    const inner = this.rpcClient.onNotification(
      RundotGameMessageId.BACK_BUTTON,
      callback,
    )

    if (!this.backButtonHandlerRegistered) {
      this.backButtonHandlerRegistered = true
      this.rpcClient
        .call(RundotGameMessageId.BACK_BUTTON_HANDLER_SET, { active: true })
        .catch(() => {})
    }

    let unsubscribed = false
    return {
      unsubscribe: () => {
        if (unsubscribed) return
        unsubscribed = true
        inner.unsubscribe()
        this.backButtonHandlerRegistered = false
        this.rpcClient
          .call(RundotGameMessageId.BACK_BUTTON_HANDLER_SET, { active: false })
          .catch(() => {})
      },
    }
  }
}
