﻿import { RundotGameAPI } from '../rundot-game-api/types.ts'
import { Host } from '../Host.ts'

export * from './AnalyticsApi'
export * from './MockAnalyticsApi'
export * from './RpcAnalyticsApi'

export function initializeAnalytics(rundotGameApiInstance: RundotGameAPI, host: Host) {
  rundotGameApiInstance.logCustomEvent = async (options) => {
    const result = await host.analytics.recordCustomEvent(
      options.eventName,
      options.params,
    )
  }

  rundotGameApiInstance.analytics = host.analytics
}
