import {
  RoomsApi,
  CreateRoomOptions,
  JoinOrCreateRoomOptions,
  JoinOrCreateResult,
  ListRoomsOptions,
  RoomSubscriptionOptions,
  RoomDataUpdate,
  RoomMessageEvent,
  ProposedMoveEvent,
  ProposeMoveRequest,
  ProposeMoveResult,
  ValidateMoveVerdict,
  ValidateMoveResult,
  UpdateRoomDataOptions,
  RoomMessageRequest,
  StartRoomGameOptions,
} from './RoomsApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { RundotGameTransport } from '../RundotGameTransport'
import {
  RundotGameRoom,
  RundotGameRoomPayload,
  RoomEnvelopeResponse,
  RoomsEnvelopeResponse,
  JoinOrCreateRoomEnvelopeResponse,
} from './RundotGameRoom'
import {
  setupRoomNotifications,
  type RoomNotificationSubscriptionState,
} from './setupRoomNotifications'

export class RpcRoomsApi implements RoomsApi {
  private readonly rpcClient: RpcClient
  private readonly subscriptions: RoomNotificationSubscriptionState

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
    this.subscriptions = {
      data: {},
      messages: {},
      gameEvents: {},
    }
  }

  /**
   * Get the subscription state for external access (used by setupRoomNotifications)
   */
  getSubscriptions(): RoomNotificationSubscriptionState {
    return this.subscriptions
  }

  /**
   * Set up room notification routing from the transport
   */
  setupNotifications(transport: RundotGameTransport): void {
    setupRoomNotifications(transport, () => this.getSubscriptions())
  }

  async createRoomAsync(options: CreateRoomOptions): Promise<RundotGameRoom> {
    const response = await this.rpcClient.call<RoomEnvelopeResponse>(
      RundotGameMessageId.H5_ROOM_CREATE,
      {
        options: options,
      },
    )
    return new RundotGameRoom(response.room)
  }

  async joinOrCreateRoomAsync(
    options: JoinOrCreateRoomOptions,
  ): Promise<JoinOrCreateResult> {
    const response = await this.rpcClient.call<JoinOrCreateRoomEnvelopeResponse>(
      RundotGameMessageId.H5_ROOM_JOIN_OR_CREATE,
      {
        options: options,
      },
    )

    return {
      action: response.action,
      room: new RundotGameRoom(response.room),
      playersJoined: response.playersJoined,
    }
  }

  async joinRoomByCodeAsync(roomCode: string): Promise<RundotGameRoom> {
    const response = await this.rpcClient.call<RoomEnvelopeResponse>(
      RundotGameMessageId.H5_ROOM_JOIN_BY_CODE,
      {
        roomCode: roomCode,
      },
    )
    return new RundotGameRoom(response.room)
  }

  // Get user's rooms with optional filtering
  async getUserRoomsAsync(options: ListRoomsOptions = {}): Promise<RundotGameRoom[]> {
    const response = await this.rpcClient.call<RoomsEnvelopeResponse | RundotGameRoomPayload[]>(
      RundotGameMessageId.H5_ROOM_GET_USER_ROOMS,
      {
        includeArchived: options.includeArchived ?? false,
      },
    )

    const rawRooms = Array.isArray(response)
      ? response
      : response?.rooms

    if (!Array.isArray(rawRooms)) {
      console.warn('[RUN] getUserRoomsAsync: Unexpected response format:', response)
      return []
    }

    // Convert raw room data to RundotGameRoom objects and filter out corrupted entries
    const rundotGameRooms: RundotGameRoom[] = []

    for (const roomData of rawRooms) {
      // Skip rooms with missing canonical ID
      if (!roomData.id) {
        console.warn('[RUN] getUserRooms: Skipping room with missing ID:', roomData)
        continue
      }

      try {
        const rundotGameRoom = new RundotGameRoom(roomData)
        rundotGameRooms.push(rundotGameRoom)
      } catch (error) {
        console.warn(
          '[RUN] getUserRooms: Failed to create RundotGameRoom object:',
          error,
          roomData,
        )
        // Continue processing other rooms
      }
    }

    return rundotGameRooms
  }

  /** @deprecated Rooms V1 is unsupported. Hold state in your realtime `GameRoom` class. */
  async updateRoomDataAsync(
    room: RundotGameRoom,
    updates: Record<string, unknown>,
    options: UpdateRoomDataOptions = {},
  ): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_ROOM_UPDATE_DATA,
      {
        roomId: room.id,
        updates,
        merge: options.merge ?? true,
      },
    )
  }

  async getRoomDataAsync(room: RundotGameRoom): Promise<Record<string, unknown>> {
    const data = await this.rpcClient.call<Record<string, unknown>>(
      RundotGameMessageId.H5_ROOM_GET_DATA,
      {
        roomId: room.id,
      },
    )
    return data
  }

  async sendRoomMessageAsync(
    rundotGameRoom: RundotGameRoom,
    request: RoomMessageRequest,
  ): Promise<string> {
    const messageId = await this.rpcClient.call<string>(
      RundotGameMessageId.H5_ROOM_SEND_MESSAGE,
      {
        roomId: rundotGameRoom.id,
        message: request.message,
        metadata: request.metadata,
      },
    )
    return messageId
  }

  async leaveRoomAsync(room: RundotGameRoom): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_ROOM_LEAVE,
      {
        roomId: room.id,
      },
    )
  }

  async kickPlayerAsync(
    room: RundotGameRoom,
    targetProfileId: string,
    options: { reason?: string } = {},
  ): Promise<void> {
    const args: Record<string, unknown> = {
      roomId: room.id,
      targetProfileId,
    }

    // Avoid sending `undefined` optional fields (Firestore cannot store `undefined`)
    if (options.reason !== undefined) {
      args.reason = options.reason
    }

    await this.rpcClient.call<void>(RundotGameMessageId.H5_ROOM_KICK_PLAYER, args)
  }

  async startRoomGameAsync(
    room: RundotGameRoom,
    options: StartRoomGameOptions = {},
  ): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_ROOM_START_GAME,
      {
        roomId: room.id,
        options: {
          gameConfig: options.gameConfig ?? {},
          turnOrder: options.turnOrder ?? null,
        },
      },
    )
  }

  async proposeMoveAsync(
    room: RundotGameRoom,
    proposalPayload: ProposeMoveRequest,
  ): Promise<ProposeMoveResult> {
    const args: Record<string, unknown> = {
      roomId: room.id,
      gameSpecificState: proposalPayload.gameSpecificState,
      moveType: proposalPayload.moveType,
    }

    // Avoid sending `undefined` optional fields (Firestore cannot store `undefined`)
    if (proposalPayload.clientContext !== undefined) {
      args.clientContext = proposalPayload.clientContext
    }

    if (proposalPayload.clientProposalId !== undefined) {
      args.clientProposalId = proposalPayload.clientProposalId
    }

    const data = await this.rpcClient.call<ProposeMoveResult>(
      RundotGameMessageId.H5_ROOM_PROPOSE_MOVE,
      args,
    )
    return data
  }

  async validateMoveAsync(
    _room: RundotGameRoom,
    moveId: string,
    verdict: ValidateMoveVerdict,
  ): Promise<ValidateMoveResult> {
    // TODO: Implement actual validation logic when peer validation is added
    // For now, just return success to maintain compatibility
    return {
      success: true,
      moveId,
      isValid: verdict.isValid,
      reason: verdict.reason,
    }
  }

  async subscribeAsync(
    room: RundotGameRoom,
    options: RoomSubscriptionOptions = {},
  ): Promise<() => void> {
    const roomId = room.id

    const existingData = this.subscriptions.data[roomId]
    const existingMessages = this.subscriptions.messages[roomId]
    const existingGameEvents = this.subscriptions.gameEvents[roomId]

    const subscribeToData =
      Boolean(options.onData) && (existingData?.length ?? 0) === 0
    const subscribeToMessages =
      Boolean(options.onMessages) && (existingMessages?.length ?? 0) === 0
    const subscribeToProposedMoves =
      Boolean(options.onGameEvents) &&
      (existingGameEvents?.length ?? 0) === 0

    if (subscribeToData || subscribeToMessages || subscribeToProposedMoves) {
      try {
        await this.rpcClient.call(RundotGameMessageId.H5_ROOM_SUBSCRIBE, {
          roomId,
          subscribeToData,
          subscribeToMessages,
          subscribeToProposedMoves,
        })
      } catch (error) {
        console.error('[RUN] Failed to set up room subscription:', error)
        throw error
      }
    }

    if (options.onData) {
      if (!this.subscriptions.data[roomId]) {
        this.subscriptions.data[roomId] = []
      }
      this.subscriptions.data[roomId].push(options.onData)
    }

    if (options.onMessages) {
      if (!this.subscriptions.messages[roomId]) {
        this.subscriptions.messages[roomId] = []
      }
      this.subscriptions.messages[roomId].push(options.onMessages)
    }

    if (options.onGameEvents) {
      if (!this.subscriptions.gameEvents[roomId]) {
        this.subscriptions.gameEvents[roomId] = []
      }
      this.subscriptions.gameEvents[roomId].push(options.onGameEvents)
    }

    let disposed = false
    return () => {
      if (disposed) return
      disposed = true

      if (options.onData) {
        const callbacks = this.subscriptions.data[roomId]
        if (callbacks) {
          const index = callbacks.indexOf(options.onData)
          if (index > -1) {
            callbacks.splice(index, 1)
          }
        }
      }

      if (options.onMessages) {
        const callbacks = this.subscriptions.messages[roomId]
        if (callbacks) {
          const index = callbacks.indexOf(options.onMessages)
          if (index > -1) {
            callbacks.splice(index, 1)
          }
        }
      }

      if (options.onGameEvents) {
        const callbacks = this.subscriptions.gameEvents[roomId]
        if (callbacks) {
          const index = callbacks.indexOf(options.onGameEvents)
          if (index > -1) {
            callbacks.splice(index, 1)
          }
        }
      }

      const hasAnySubscriptions =
        (this.subscriptions.data[roomId]?.length ?? 0) > 0 ||
        (this.subscriptions.messages[roomId]?.length ?? 0) > 0 ||
        (this.subscriptions.gameEvents[roomId]?.length ?? 0) > 0

      if (!hasAnySubscriptions) {
        // Fire-and-forget cleanup: the SDK does not need (and cannot
        // meaningfully recover from) an unsubscribe response. Using
        // notify() avoids spurious 30s timeout errors when the iframe is
        // throttled (e.g. backgrounded tab) and the host's response is
        // late.
        this.rpcClient.notify(RundotGameMessageId.H5_ROOM_UNSUBSCRIBE, {
          roomId,
        })
      }
    }
  }
}
