import { RundotGameAPI } from '../rundot-game-api/types'
import { Host } from '../Host'

export * from './SystemApi'
export * from './HostSystemApi'
export * from './MockSystemApi'
export type { SafeArea } from '../Host'

export function initializeSystem(rundotGameApi: RundotGameAPI, host: Host) {
  // Add system namespace to RundotGameAPI - this is the ONLY way to access system APIs
  rundotGameApi.system = host.system
  
  // Add deprecated top-level platform detection methods (redirect to system)
  rundotGameApi.isMobile = () => {
    console.warn(
      '[RUN] DEPRECATED: RundotGameAPI.isMobile() is deprecated. ' +
      'Use RundotGameAPI.system.isMobile() instead.'
    )
    return host.system.isMobile()
  }
  
  rundotGameApi.isWeb = () => {
    console.warn(
      '[RUN] DEPRECATED: RundotGameAPI.isWeb() is deprecated. ' +
      'Use RundotGameAPI.system.isWeb() instead.'
    )
    return host.system.isWeb()
  }
}

