/**
 * Wire protocol types for Client ↔ Room Server WebSocket communication.
 */

/** Protocol version — bump in lockstep with server/mp-room-server */
export const PROTOCOL_VERSION = 1

// ── Client → Server ──

export interface ClientAuthMessage {
  type: 'auth'
  protocolVersion: number
  /** Firebase ID token (legacy path) */
  token?: string
  /** Opaque join ticket (preferred path) */
  ticket?: string
  roomType: string
  roomCode?: string
  action?: 'create' | 'joinOrCreate' | 'joinByCode' | 'matchmake'
  /** Internal: set automatically on reconnection */
  _roomId?: string
  reconnect?: boolean
}

export interface ClientGameMessage {
  type: 'message'
  msgType: string
  data: unknown
}

export interface ClientPingMessage {
  type: 'ping'
  ts: number
}

export interface ClientRoomSetSeatingMessage {
  type: 'room:setSeatingOpen'
  open: boolean
}

export type ClientToServerMessage =
  | ClientAuthMessage
  | ClientGameMessage
  | ClientRoomSetSeatingMessage
  | ClientPingMessage

// ── Server → Client ──

export interface ServerRoomJoinedMessage {
  type: 'room:joined'
  roomCode: string
  playerId: string
  /** Internal room identifier (used for reconnection, not user-facing) */
  _roomId: string
  players?: readonly { readonly id: string; readonly username: string; readonly avatarUrl?: string | null }[]
  maxPlayers?: number
  locked?: boolean
  isCreator?: boolean
}

export interface ServerRoomBroadcastMessage {
  type: 'room:broadcast'
  msgType: string
  data: unknown
}

export interface ServerRoomSendToMessage {
  type: 'room:sendTo'
  msgType: string
  data: unknown
}

export interface ServerRoomErrorMessage {
  type: 'room:error'
  code?: string
  message: string
}

export interface ServerRoomLockMessage {
  type: 'room:lock'
}

export interface ServerRoomUnlockMessage {
  type: 'room:unlock'
}

export interface ServerRoomPlayerJoinedMessage {
  type: 'room:playerJoined'
  playerId: string
  username: string
  avatarUrl?: string | null
}

export interface ServerRoomPlayerLeftMessage {
  type: 'room:playerLeft'
  playerId: string
}

export interface ServerPongMessage {
  type: 'pong'
  ts: number
  serverTs: number
}

/** A persisted room chat message (Req 20). Mirrors the server's ChatMessage. */
export interface ChatMessageData {
  id: string
  roomId: string
  senderId: string
  senderName?: string
  text: string
  ts: number
}

/** Server → client: a chat message delivered to a current member. */
export interface ServerChatMessage {
  type: 'chat:message'
  data: ChatMessageData
}

/** Server → client: reply to a `chat:history` request. */
export interface ServerChatHistoryMessage {
  type: 'chat:history'
  data: { messages: ChatMessageData[] }
}

/** Server → client: matchmaking request enqueued; keep polling (Req 18). */
export interface ServerMatchmakingPendingMessage {
  type: 'matchmaking:pending'
}

/** Server → client: no longer in the pool (cancelled/expired). */
export interface ServerMatchmakingIdleMessage {
  type: 'matchmaking:idle'
}

/** Server → client: ack of a `matchmaking:cancel`. */
export interface ServerMatchmakingCancelledMessage {
  type: 'matchmaking:cancelled'
}

/**
 * Server → client: the server moved this player to another room (move_player /
 * Req 19). The same socket stays open and now serves the destination room; the
 * client retargets its roomCode/_roomId so a later reconnect lands in the new
 * room.
 */
export interface ServerRoomMovedMessage {
  type: 'room:moved'
  roomCode: string
  /** Internal room identifier of the destination (used for reconnection). */
  _roomId: string
}

export interface ServerRoomReconnectingMessage {
  type: 'room:reconnecting'
}

export interface ServerRoomReconnectedMessage {
  type: 'room:reconnected'
  roomCode?: string
  playerId?: string
  _roomId?: string
}

export type ServerToClientMessage =
  | ServerRoomJoinedMessage
  | ServerRoomBroadcastMessage
  | ServerRoomSendToMessage
  | ServerRoomErrorMessage
  | ServerRoomLockMessage
  | ServerRoomUnlockMessage
  | ServerRoomPlayerJoinedMessage
  | ServerRoomPlayerLeftMessage
  | ServerPongMessage
  | ServerRoomMovedMessage
  | ServerRoomReconnectingMessage
  | ServerRoomReconnectedMessage
  | ServerChatMessage
  | ServerChatHistoryMessage
  | ServerMatchmakingPendingMessage
  | ServerMatchmakingIdleMessage
  | ServerMatchmakingCancelledMessage
