import { PreloaderApi } from './PreloaderApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'

export class RpcPreloaderApi implements PreloaderApi {
    private readonly rpcClient: RpcClient

    constructor(rpcClient: RpcClient) {
        this.rpcClient = rpcClient
    }

    async showLoadScreen(): Promise<void> {
        await this.rpcClient.call(RundotGameMessageId.H5_SHOW_LOAD_SCREEN)
    }

    async hideLoadScreen(): Promise<void> {
        await this.rpcClient.call(RundotGameMessageId.H5_HIDE_LOAD_SCREEN)
    }

    async setLoaderText(text: string): Promise<void> {
        await this.rpcClient.call(RundotGameMessageId.H5_SET_LOADER_TEXT, { text })
    }

    async setLoaderProgress(progress: number): Promise<void> {
        await this.rpcClient.call(RundotGameMessageId.H5_SET_LOADER_PROGRESS, { progress })
    }
}